// ===========================================================================
// src/40-doctrine.js
// ===========================================================================
// ---------------------------------------------------------------------------
// Doctrine embedded per role. Copied from the superpowers skills (MIT, Jesse
// Vincent), adapted only where a stage has no human to ask: the spec writer
// must DECIDE and record instead of asking, and there is no approval gate.
// Embedded rather than invoked by name so the pair stays self-contained — an
// install without the plugin behaves identically.
// ---------------------------------------------------------------------------
const DOCTRINE_BRAINSTORM = "DOCTRINE FOR THIS STAGE (from the superpowers `brainstorming` skill, adapted for a run with no human to ask):\n\nHelp turn an idea into a fully formed design and spec. Classify the request first and say the\nclassification in the spec: a SPIKE (a feasibility question whose output is an answer, not code to\nkeep), a BOUNDED change (a well-scoped change to a flow that already exists in this repo \u2014 bounded\nmeasures the repo, not your familiarity with the kind of app), or ARCHITECTURAL (a new subsystem, a\nchange that restructures how components fit or alters interfaces others depend on). When in doubt,\ntake the heavier path; hidden complexity discovered mid-way upgrades the path, never downgrades it.\n\"Too simple to need a design\" is the thought that wastes the most work: simple means a short design,\nnot no design.\n\nUnderstanding the idea:\n- Check the current project state first: files, docs, recent commits, the conventions it states.\n- Assess scope before detail. If the request describes several independent subsystems, decompose:\n  name the independent pieces, how they relate, what order they should be built in, and write THIS\n  spec for the first sub-project only; list the rest under \"Out of scope, next specs\".\n- Focus on purpose, constraints, success criteria.\n- There is NO human partner in this run. Every question you would have asked, you must answer\n  yourself: pick the answer a careful colleague would pick, and record every such choice in a\n  section titled \"Decisions taken without the owner\", one row each \u2014 the question, the decision,\n  why \u2014 so the owner can overturn any of them by reading that one section. Never leave a TBD.\n\nExploring approaches:\n- Propose two or three approaches with trade-offs; lead with your recommendation and why.\n- YAGNI ruthlessly: remove unnecessary features from every approach and from the design.\n\nPresenting the design (in the spec):\n- Cover architecture, components, data flow, error handling, testing. Scale each section to its\n  complexity: a few sentences if straightforward, a few hundred words if nuanced.\n- Design for isolation and clarity: units with one purpose, well-defined interfaces, understandable\n  and testable independently. For each unit: what does it do, how do you use it, what does it depend on.\n- In an existing codebase, follow its patterns. Include targeted improvements only where an existing\n  problem affects THIS work; propose no unrelated refactoring.\n\nSpec self-review before you finish (fix inline, no re-review needed):\n1. Placeholder scan: any TBD, TODO, incomplete section or vague requirement \u2014 fix it.\n2. Internal consistency: do sections contradict each other; does the architecture match the features.\n3. Scope check: focused enough for one implementation plan, or does it need decomposition.\n4. Ambiguity check: could a requirement be read two ways \u2014 pick one and make it explicit.\n"
const DOCTRINE_WRITING_PLANS = "DOCTRINE FOR THIS STAGE (from the superpowers `writing-plans` skill):\n\nWrite a comprehensive implementation plan assuming the engineer has zero context for this codebase\nand questionable taste. Document everything they need: which files to touch for each task, the code,\nthe tests, the docs they might need to check, how to test it. Bite-sized tasks. DRY. YAGNI. TDD.\nFrequent commits. Assume a skilled developer who knows almost nothing about this toolset or problem\ndomain and does not know good test design well.\n\nScope check: if the spec covers several independent subsystems, the plan covers the first and says so.\n\nFile structure first: before defining tasks, map which files are created or modified and what each is\nresponsible for \u2014 this is where decomposition is locked in. Units with clear boundaries and interfaces;\nsmaller focused files over large ones; files that change together live together; in an existing\ncodebase follow its patterns.\n\nTask right-sizing: a task is the smallest unit that carries its own test cycle and is worth a fresh\nreviewer's gate. Fold setup, configuration, scaffolding and documentation into the task whose\ndeliverable needs them; split only where a reviewer could reject one task while approving its\nneighbour. Each task ends with an independently testable deliverable. Each STEP is one action of two\nto five minutes: write the failing test; run it and watch it fail; write the minimal implementation;\nrun it and watch it pass; commit.\n\nThe plan MUST start with this header:\n\n# [Feature Name] Implementation Plan\n\n> **For agentic workers:** this plan is executed by the verified-build engine, one task per slice,\n> each slice implemented by a fresh agent and the whole diff reviewed by a different model. Steps use `- [ ]` syntax.\n\n**Goal:** [one sentence]\n**Architecture:** [two or three sentences]\n**Tech Stack:** [key technologies]\n**Spec:** [path \u2014 the plan argues from the spec, so the spec travels with it]\n\n## Global Constraints\n[The spec's project-wide requirements, one line each, exact values copied verbatim. Every task's\nrequirements implicitly include this section.]\n\nThen a \"## File map\" (created / modified / deleted, one line per file with its responsibility) and a\n\"## File-overlap table\" (for every file two or more tasks touch: the tasks, in order \u2014 the engine\nserialises those tasks, so keep chains short and prefer merging a chain longer than four into fewer,\nlarger tasks).\n\nEach task has this structure:\n\n### Task N: [Component Name]\n**Files:** Create / Modify (`exact/path.py:123-145`, measured with grep -n or sed -n on the CURRENT\ntree, never estimated) / Test.\n**Interfaces:** Consumes (what this task uses from earlier tasks \u2014 exact signatures) / Produces (what\nlater tasks rely on \u2014 exact names, parameter and return types; an implementer sees only its own task).\n- [ ] **Step 1: Write the failing test** \u2014 the real test code, in a fenced block.\n- [ ] **Step 2: Run it to verify it fails** \u2014 the exact command and the expected failure.\n- [ ] **Step 3: Write the minimal implementation** \u2014 the real code, in a fenced block.\n- [ ] **Step 4: Run it to verify it passes** \u2014 the exact command.\n- [ ] **Step 5: Run the repo's own check** and **commit** \u2014 the exact commit message in the repo's convention.\n\nNo placeholders. These are plan failures, never write them: \"TBD\", \"TODO\", \"implement later\", \"add\nappropriate error handling\", \"add validation\", \"handle edge cases\", \"write tests for the above\" without\nthe test code, \"similar to Task N\" (repeat the code), steps that describe without showing (code blocks\nare required for code steps), references to names not defined in any task.\n\nSelf-review after writing (fix inline, then stop):\n1. Spec coverage: every requirement in the spec points to a task that implements it; add tasks for gaps.\n2. Placeholder scan: search the plan for every pattern above.\n3. Type consistency: names, signatures and property names used in later tasks match what earlier\n   tasks defined.\n"
const DOCTRINE_TDD = "DOCTRINE (from the superpowers `test-driven-development` and `verification-before-completion` skills):\n\nThe iron law: NO PRODUCTION CODE WITHOUT A FAILING TEST FIRST. Write one minimal test showing what\nshould happen; run it and WATCH IT FAIL, for the expected reason (feature missing, not a typo \u2014 a test\nthat passes immediately is testing existing behaviour, fix the test); write the simplest code that\npasses; run it and watch it pass with the other tests still green and the output pristine; refactor\nonly after green, adding no behaviour. Wrote code before the test? Delete it and start from the test.\nGood tests: one behaviour each, a name that describes the behaviour, real code rather than mocks\nunless a mock is unavoidable, asserting on behaviour rather than on the mock. Name, before writing a\ntest, the production change that would make it fail. Keep test-only code in test utilities, never in\nproduction classes. Where the repo's only checks are lint/validate/build, those are the red and green.\n\nEvidence before claims, always: NO COMPLETION CLAIM WITHOUT FRESH VERIFICATION EVIDENCE. Before you\nreport any status: identify the command that proves it, run the FULL command fresh, read the whole\noutput and the exit code, and only then make the claim \u2014 with the evidence. \"Should pass\", \"looks\ncorrect\", \"I'm confident\", a previous run, a partial run: none of these is evidence. A regression test\nis proven by red-green: it must fail on the old code and pass on the new. Requirements are met when you\nre-read the task, make a checklist, and verify each line, not when the tests pass.\n"
const DOCTRINE_DEBUG = "DOCTRINE (from the superpowers `systematic-debugging` skill, plus TDD and verification):\n\nNO FIXES WITHOUT ROOT CAUSE INVESTIGATION FIRST. Phase 1, root cause: read the error and the finding's\nfailure_scenario completely; reproduce it (a failing test, or a one-off script if the repo has no test\nframework); check what changed recently (git log, git diff); in a multi-component path add evidence at\neach boundary and see WHERE it breaks; trace a bad value back to where it originates and fix at the\nsource, not the symptom. Phase 2, pattern: find working examples of the same shape in this codebase,\nread the reference completely, list every difference. Phase 3, hypothesis: state ONE specific hypothesis,\nmake the smallest change that tests it, one variable at a time; if it did not work form a new\nhypothesis rather than stacking fixes. Phase 4, implement: a failing test that reproduces the finding\nFIRST, then one fix at the root cause, no \"while I'm here\" improvements, no bundled refactoring; then\nverify \u2014 the new test passes, no other test broke, the scenario is actually resolved. If three fixes\nhave failed, stop: the pattern is architectural, report it as disputed-with-evidence rather than\nattempting a fourth. Under time pressure the process is faster than guessing, not slower.\n\nEvidence before claims, always: identify the command that proves the fix, run it in full, read the\noutput, and only then claim it. A regression test is proven by red-green: revert the fix and watch it\nfail, restore it and watch it pass.\n"
const DOCTRINE_REVIEW_CALIBRATION = "CALIBRATION (from the superpowers code-reviewer template): categorise by ACTUAL severity \u2014 not\neverything is critical. Be specific (file:line, not vague), explain WHY each issue matters and how to\nfix it if not obvious, and give a clear verdict. Never say \"looks good\" without checking, never mark a\nnitpick critical, never report on code you did not read, never be vague (\"improve error handling\"). If a\ndeviation from the plan looks intentional, say so as a deviation rather than a defect; if the plan\nitself is wrong, say that. Your review is read-only on this checkout: never mutate the working tree,\nthe index, HEAD or branch state; if you need another revision, use a separate `git worktree` in a\ntemporary directory. Do the whole review yourself: never spawn a subagent to review part of it.\n"
const DOCTRINE_RECEIVING = "DOCTRINE FOR FOLDING IN A REVIEW (from the superpowers `receiving-code-review` skill):\n\nReview feedback needs technical evaluation, not performance. For each finding: READ it completely;\nrestate the requirement in your own words; VERIFY it against the document and the codebase; EVALUATE\nwhether it is right for THIS repo; then RESPOND \u2014 fold it in, or refute it with technical reasoning and\nconcrete evidence (a command you ran, a line you read). Never fold in a finding you have not verified;\nnever refuse one merely because it is inconvenient. Push back when the finding breaks something that\nexists, lacks context the document states, violates YAGNI, or contradicts a decision the owner already\nrecorded \u2014 and in that last case leave the owner's decision standing and say why. Fold in one finding at\na time; keep the document consistent after each (a change in one section usually has echoes in the\nFile map, the overlap table, the self-review and the tests). No gratitude, no \"you're absolutely\nright\": state what changed. Record the disposition of every finding, folded or refuted, in a fold-in\nsection at the end of the document.\n"

// ===========================================================================
// src/50-helpers.js
// ===========================================================================
// ---------------------------------------------------------------------------
// Pure helpers. No agent calls, no run state: paths and their overlap, slice
// grouping, prices, answers, finding ids, the review verdict, the orchestrator's
// list, and the fold-in proof. test/helpers.test.js pulls these out by name, so
// keep each one a top-level `function name(...) {}`.
// ---------------------------------------------------------------------------
// Repo-relative paths for the same file arrive spelled differently ("./src/a.py",
// "src/a.py", "src\\a.py", "src/./a.py", "/src/a.py", "src/../src/a.py"). Conflict
// detection compares these strings, so an unnormalised pair reads as disjoint and two
// agents get sent at one file — the exact failure the grouping exists to prevent.
// Separators are collapsed, "." and ".." segments resolved, leading and trailing "/"
// dropped.
function normPath(p) {
  const raw = String(p || '').trim().replace(/\\/g, '/')
  const out = []
  for (const seg of raw.split('/')) {
    if (seg === '' || seg === '.') continue
    if (seg === '..') { out.pop(); continue }
    out.push(seg)
  }
  return out.join('/')
}

// Two declared paths overlap when they are the same file, when one is a directory
// holding the other ("modules/vpc" vs "modules/vpc/main.tf" — the slicer is told to
// declare directories for Terraform modules), or when one is a glob that could match
// the other. A glob is turned into a regex where `**` spans directories and `*` one
// segment; a glob against a glob overlaps when either's literal prefix covers the
// other. Under-detection sends two agents at one file, so when in doubt, overlap.
function pathsOverlap(a, b) {
  if (a === b) return true
  if (a.startsWith(b + '/') || b.startsWith(a + '/')) return true
  const ga = a.includes('*'), gb = b.includes('*')
  if (!ga && !gb) return false
  // `**/` spans zero or more directories (src/**/*.py covers src/a.py as well as
  // src/deep/a.py), a bare `**` spans anything, `*` one segment.
  const globRe = (g) => {
    let re = ''
    for (let i = 0; i < g.length; i++) {
      if (g.startsWith('**/', i)) { re += '(?:.*/)?'; i += 2; continue }
      if (g.startsWith('**', i)) { re += '.*'; i += 1; continue }
      if (g[i] === '*') { re += '[^/]*'; continue }
      re += g[i].replace(/[.+^${}()|[\]\\?]/, '\\$&')
    }
    return new RegExp('^' + re + '(/.*)?$')
  }
  if (ga && !gb) return globRe(a).test(b)
  if (gb && !ga) return globRe(b).test(a)
  const pa = a.slice(0, a.indexOf('*')), pb = b.slice(0, b.indexOf('*'))
  return pa.startsWith(pb) || pb.startsWith(pa)
}

// Planners write `src/{a,b}.py` for two files. Expand it, or the pair compares
// as one exotic path that matches nothing and both slices read as disjoint.
function expandBraces(p) {
  const m = /^(.*?)\{([^{}]*)\}(.*)$/.exec(p)
  if (!m) return [p]
  return m[2].split(',').flatMap((alt) => expandBraces(m[1] + alt.trim() + m[3]))
}

// A slice's declared footprint. Under-detection is the dangerous direction: it
// puts two agents inside one file at the same time. Over-detection costs only
// wall-clock, never context — so when in doubt, collide.
function declaredFiles(s, quiet) {
  const out = new Set()
  for (const raw of s.files || []) {
    for (const p of expandBraces(String(raw || ''))) {
      const f = normPath(p)
      if (!f) continue
      if (f.includes('*') && !quiet) {
        log('WARNING: slice ' + s.id + ' declared a glob (' + f + ') — it collides with every declared path it could match')
      }
      out.add(f)
    }
  }
  return out
}

// Slices that touch a common file cannot run concurrently. Union them into a
// group; the group's slices run SEQUENTIALLY — one agent each, never merged
// into one context — and groups run in parallel. A slice with no declared
// files gets its own group marked EXCLUSIVE, because an unknown footprint cannot
// be proven disjoint from anything: the engine runs such a group with nothing
// else live, after the grouped slices. Within a group the slices keep the PLAN'S order: a slice
// that bridges two earlier groups used to be appended ahead of the second
// group's slices, so Task 3 ran before the Task 2 it consumed from.
function groupByFileConflict(slices) {
  const groups = []
  slices.forEach((s, index) => {
    const files = declaredFiles(s)
    const entry = { slice: s, index }
    if (files.size === 0) {
      log('WARNING: slice ' + s.id + ' declared no files — footprint unknown, so it runs with nothing else live')
      groups.push({ entries: [entry], files })
      return
    }
    const hits = groups.filter((g) => [...files].some((f) => [...g.files].some((h) => pathsOverlap(f, h))))
    if (hits.length === 0) {
      groups.push({ entries: [entry], files })
      return
    }
    const target = hits[0]
    target.entries.push(entry)
    for (const f of files) target.files.add(f)
    for (const extra of hits.slice(1)) {
      target.entries.push(...extra.entries)
      for (const f of extra.files) target.files.add(f)
      const at = groups.indexOf(extra)
      if (at >= 0) groups.splice(at, 1)
    }
  })
  return groups
    .map((g) => ({ ...g, entries: g.entries.sort((a, b) => a.index - b.index) }))
    .sort((a, b) => a.entries[0].index - b.entries[0].index)
    .map((g) => ({ slices: g.entries.map((e) => e.slice), files: g.files, exclusive: g.files.size === 0 }))
}

// The orchestrator's slices (from:'slices') are checked here before anything is spent: a
// malformed slice is an argument error, not a lane's. Returns one message per problem,
// empty when the list is usable. The text fields must BE strings, not merely coerce to
// one: `String({text:'do a'})` is "[object Object]", and an implementer plus two review
// passes would be paid to build from it. `id` may also be a number (s1 or 1). `files` may
// be empty (an unknown footprint runs alone), but it must be a list of strings; extra
// fields are ignored.
function sliceArgErrors(raw, max) {
  if (!Array.isArray(raw)) return ['slices must be an array of {id, title, prompt, files, done_when}']
  if (!raw.length) return ['slices is empty']
  const out = []
  if (raw.length > max) out.push(raw.length + ' slices exceed maxSlices (' + max + ', which the engine caps at 20): this is not a small build')
  const seen = new Set()
  raw.forEach((s, i) => {
    const at = 'slices[' + i + ']'
    if (!s || typeof s !== 'object' || Array.isArray(s)) { out.push(at + ' is not an object'); return }
    const id = typeof s.id === 'string' || typeof s.id === 'number' ? String(s.id).trim() : ''
    if (!id) out.push(at + ' has no id (a string or a number)')
    else if (seen.has(id)) out.push(at + ' repeats id "' + id + '"')
    seen.add(id)
    for (const k of ['title', 'prompt', 'done_when']) {
      if (typeof s[k] !== 'string' || !s[k].trim()) out.push(at + (id ? ' (' + id + ')' : '') + ' has no ' + k + ' (a non-empty string)')
    }
    if (!Array.isArray(s.files) || s.files.some((f) => typeof f !== 'string' || !f.trim())) {
      out.push(at + (id ? ' (' + id + ')' : '') + ' needs files: an array of repo-relative path strings (empty is allowed and means an unknown footprint)')
    }
  })
  return out
}

// After the implement phase: every file an implementer reports touching that is outside
// its declared set AND inside another group's declared set was edited while that group
// may have been live in the same tree. That is the collision the grouping exists to
// prevent, and no prompt can rule it out — so it is checked here and held against the run.
function footprintViolations(built, groups) {
  const out = []
  const groupOf = (id) => groups.find((g) => g.slices.some((x) => x.id === id))
  for (const b of built) {
    if (!b || !b.impl) continue
    const declared = [...declaredFiles(b.slice, true)]
    const mine = groupOf(b.slice.id)
    for (const r of b.impl.slice_results || []) {
      for (const raw of r.files_touched || []) {
        const f = normPath(raw)
        if (!f || declared.some((d) => pathsOverlap(f, d))) continue
        const collides = groups
          .filter((g) => g !== mine && [...g.files].some((h) => pathsOverlap(f, h)))
          .flatMap((g) => g.slices.map((x) => x.id))
        if (collides.length) out.push({ slice: b.slice.id, file: f, collides_with: collides })
      }
    }
  }
  return out
}

// A finding's footprint for patch grouping: every file the reviewer says a fix would
// touch (`files`, which should include the test file), else the single `file`, else
// nothing — and nothing means an exclusive group.
function patchFootprint(f) {
  if (Array.isArray(f.files) && f.files.length) return f.files.map(String)
  return f.file ? [String(f.file)] : []
}

// Seconds per phase, summed over its lanes, plus the run's wall clock so far. Lanes
// that ran in parallel are summed, not overlapped: the figure is agent time, and
// the run total is the wall clock.
function timingByPhase(timings, runSeconds) {
  const by = {}
  for (const t of timings || []) { by[t.phase || 'other'] = (by[t.phase || 'other'] || 0) + (t.seconds || 0) }
  return { run_wall_clock_seconds: runSeconds, agent_seconds_by_phase: by, lanes: timings || [] }
}

function severityRank(sev) {
  if (sev === 'critical') return 0
  if (sev === 'major') return 1
  return 2
}

// A price override is merged per field and only where the value is a finite number;
// a model the defaults do not know is ignored (the estimate has no profile row for it).
function mergePrices(defaults, override) {
  const out = {}
  for (const model of Object.keys(defaults)) {
    out[model] = { ...defaults[model] }
    const row = override && typeof override === 'object' && override[model] && typeof override[model] === 'object' ? override[model] : null
    if (!row) continue
    for (const k of Object.keys(defaults[model])) {
      if (Number.isFinite(row[k]) && row[k] >= 0) out[model][k] = row[k]
    }
  }
  return out
}

// args.answers as a list of {id, answer} or an {id: answer} object, sorted by id.
function parseAnswers(raw) {
  let list = []
  if (Array.isArray(raw)) {
    list = raw.filter((a) => a && a.id).map((a) => ({ id: String(a.id), answer: String(a.answer || '') }))
  } else if (raw && typeof raw === 'object') {
    list = Object.keys(raw).map((k) => ({ id: String(k), answer: String(raw[k] || '') }))
  }
  return list.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
}

// Everything the orchestrator must close by hand, at EVERY severity, sorted critical
// first: what the final review left standing; every finding a round handed off (below
// PATCH_SEVERITY) or deferred (past the per-round cap); and every finding a round tried
// to patch that did not come back closed — the patcher returned nothing, failed, or
// disputed it. A later review that simply did not mention one of THOSE has not closed
// it; only a final-review finding whose `re_raises` names it supersedes it (then the
// newer entry stands and the old one is dropped). A patch reported fixed is closed on
// the patcher's word plus the re-review's silence — the re-review reads every patch
// diff and is told to re-raise what is not genuinely closed; that is a deliberate
// trade, not an oversight. With no final review at all, nothing is treated as closed.
function collectForOrchestrator(openFindings, rounds, hasFinalReview) {
  const out = []
  const seen = new Set()
  const superseded = new Set()
  const add = (f, source) => {
    if (!f || !f.id || seen.has(f.id) || superseded.has(f.id)) return
    seen.add(f.id)
    out.push({ ...f, source })
  }
  for (const f of openFindings || []) {
    if (f && f.re_raises) superseded.add(String(f.re_raises))
    add(f, 'final review')
  }
  for (const r of rounds || []) {
    for (const p of r.patched || []) {
      const f = p && p.finding
      if (!f) continue
      const status = p.patch ? p.patch.status : null
      if (!hasFinalReview) add(f, 'patched in round ' + r.round + ', but there was no final review to confirm it closed')
      else if (!p.patch) add(f, 'no patch: the patcher returned nothing in round ' + r.round)
      else if (status === 'disputed') add(f, 'disputed by the patcher in round ' + r.round + ' — judge the evidence: ' + String(p.patch.notes || '').slice(0, 300))
      else if (status !== 'fixed') add(f, 'patch ' + status + ' in round ' + r.round)
    }
    for (const f of r.handed_off || []) add(f, 'handed off in round ' + r.round + ' (below the auto-patch severity)')
    for (const f of r.deferred || []) add(f, 'deferred in round ' + r.round + ' (past the per-round cap)')
  }
  return out.sort((a, b) => severityRank(a.severity) - severityRank(b.severity))
}

// `clean`, `diff_reviewed`, `executed` and `findings` are independent fields in the
// schema, and a reviewer can return any combination. The engine derives clean from
// the others: a review is clean only if the diff was read, nothing was found AND —
// where the repo has a check command — the reviewer ran it. The adversary is the only
// lane that executes anything after the implementers' own self-reported runs, so a
// read-only review cannot be clean there. The reviewer's own boolean is kept as
// `claimed_clean` so a contradiction is visible.
function judgeReview(rev, hasChecks) {
  if (!rev) return rev
  const findings = Array.isArray(rev.findings) ? rev.findings : []
  const executed = rev.executed === true
  const clean = rev.diff_reviewed === true && findings.length === 0 && (!hasChecks || executed)
  if (rev.clean === true && !clean) {
    log('WARNING: the reviewer said clean:true ' + (findings.length ? 'but listed ' + findings.length + ' finding(s)' : rev.diff_reviewed !== true ? 'without reading the diff' : 'without running the check') + ' — treated as NOT clean')
  }
  return { ...rev, findings, clean, executed, claimed_clean: rev.clean === true, dirty_paths: String(rev.dirty_paths || '').replace(/\s+$/, '') }
}

function looksLikePath(t) {
  return /^[\w./-]+\.md$/.test(t.trim()) && !/\s/.test(t.trim())
}

// Questions are namespaced by stage ("spec:Q1") so an answer given for the spec's
// pause is never mistaken for a plan question of the same local id, and so the
// apply-answers prompt for the spec stays byte-identical across a later resume.
// Two DIFFERENT questions (or findings) that arrive with the same local id — the spec
// writer's Q1 and the reviewer's Q1 — are both kept; the second is suffixed "-2". Only
// an item whose id AND text repeat is a duplicate and dropped.
function namespaced(stage, qs) {
  const seen = new Map()
  const out = []
  for (const q of qs || []) {
    if (!q || !q.id) continue
    const base = stage + ':' + String(q.id).replace(/^\w+:/, '')
    const text = String(q.question || q.claim || '')
    let id = base
    for (let n = 2; seen.has(id) && seen.get(id) !== text; n++) id = base + '-' + n
    if (seen.has(id)) continue
    seen.set(id, text)
    out.push({ ...q, id })
  }
  return out
}

// A finding is folded in when the document changed, not when a reviewer says so. Every
// finding leaves at least a row in the fold-in record, so a review with findings must
// report a NEW commit (not the writer's, not the previous round's) whose `git show --stat`
// lists the document. Returns null when that holds, else what is missing.
function docEditUnproven(findingCount, sha, stat, docPath, priorSha) {
  if (!findingCount) return null
  const s = String(sha || '').trim()
  const p = String(priorSha || '').trim()
  if (!s) return 'reported no commit'
  if (p && (s.startsWith(p) || p.startsWith(s))) return 'reported the previous commit on the document (' + s.slice(0, 8) + '), not a new one'
  const base = String(docPath || '').split('/').pop()
  if (!base || !statListsDoc(stat, docPath)) return 'showed a `git show --stat` that does not list ' + docPath
  return null
}

// `git show --stat` wraps its path column to a terminal width and elides a long path from the
// LEFT with `...`, so a path this engine writes itself (`docs/specs/<yyyy-mm-dd>-<slug>.md`) can
// come back as `...-<slug>.md` — the basename's own date prefix gone. A literal `includes(base)`
// then fails on a fold-in that genuinely happened; on 2026-09-14 that stopped a run at
// `spec-review` twice, reviewer and editor lane alike, on a spec both had correctly committed.
// So compare the way git prints it: take each stat row's path cell, drop a leading `...`, and
// accept the row when the document's full path ends with what is left.
function statListsDoc(stat, docPath) {
  const full = String(docPath || '').trim()
  if (!full) return false
  const base = full.split('/').pop()
  const text = String(stat || '')
  if (text.includes(full) || text.includes(base)) return true
  for (const line of text.split('\n')) {
    // a diffstat row is ` <path> | <n> <+-/Bin>`; the rename form ` a => b` keeps its target last
    const bar = line.indexOf('|')
    if (bar < 0) continue
    let cell = line.slice(0, bar).trim()
    if (!cell) continue
    const arrow = cell.lastIndexOf('=>')
    if (arrow >= 0) cell = cell.slice(arrow + 2).trim().replace(/\}$/, '')
    if (!cell.startsWith('...')) continue
    const tail = cell.slice(3)
    if (tail && full.endsWith(tail)) return true
  }
  return false
}

// ===========================================================================
// src/60-estimate.js
// ===========================================================================
// ---------------------------------------------------------------------------
// Token profile per agent, in MILLIONS of tokens: cache reads, cache writes,
// output. Measured over six runs on one repo, 9–11 Sep 2026 (262 agents, ~2.3B
// cached-read tokens, reconstructed from every agent's transcript). The front
// half (spec/plan writers, document reviewers, fold-ins, recorder) had not run
// when this was written; those rows are ASSUMPTIONS and are labelled so in the
// estimate. Refine them from a run's transcripts once there are some.
// ---------------------------------------------------------------------------
const PROFILE = {
  recon: { model: CODER, cache: 5.5, write: 0.2, out: 0.017, measured: true },
  slice: { model: JUDGE, cache: 1.0, write: 0.2, out: 0.015, measured: true },
  implement: { model: CODER, cache: 13.0, write: 0.17, out: 0.025, measured: true },   // per slice
  review: { model: JUDGE, cache: 17.0, write: 0.45, out: 0.011, measured: true },      // per adversarial pass (now also runs the check)
  patch: { model: CODER, cache: 12.0, write: 0.08, out: 0.030, measured: true },       // per patched finding
  // The five document rows follow docWriter / docJudge, so the cost gate prices the run
  // the caller actually asked for: on the default tiers this is what it always was, and
  // a `docWriter:'opus', docJudge:'fable'` run shows its front half at roughly double
  // before a line of code is written. plan_index stays on the CODER tier deliberately —
  // it only re-measures line numbers in a document that already exists.
  spec: { model: DOC_WRITER, cache: 10.0, write: 0.3, out: 0.030, measured: false },     // on the CODER tier since v1.5.0
  doc_review: { model: DOC_JUDGE, cache: 18.0, write: 0.4, out: 0.035, measured: false },// reviews AND folds in (spec 7.6+4.7M / plan 19+6.5M cache measured as two lanes on 2026-09-11)
  plan_doc: { model: DOC_WRITER, cache: 20.0, write: 0.4, out: 0.060, measured: false }, // on the CODER tier since v1.5.0
  plan_review: { model: DOC_JUDGE, cache: 25.0, write: 0.4, out: 0.020, measured: false },
  answers: { model: DOC_JUDGE, cache: 8.0, write: 0.2, out: 0.015, measured: false },
  plan_index: { model: CODER, cache: 1.5, write: 0.05, out: 0.003, measured: false },
  probe: { model: CODER, cache: 0.01, write: 0.005, out: 0.0002, measured: false },      // per model probed
}

function priceOf(prices, model) {
  return prices[model] || prices.opus
}

function lineCost(row, prices, n) {
  const p = priceOf(prices, row.model)
  const usd = n * (row.cache * p.cache_read + row.write * p.cache_write + row.out * p.out)
  return { agents: n, model: row.model, measured: row.measured,
    cache_mtok: +(n * row.cache).toFixed(1), write_mtok: +(n * row.write).toFixed(2), out_mtok: +(n * row.out).toFixed(3),
    usd: +usd.toFixed(2) }
}

function estimateRun(profile, prices, spent, ahead) {
  // spent / ahead: { <profile key>: count }. Returns the breakdown and the totals.
  const lines = {}
  let spentUsd = 0
  let aheadUsd = 0
  let assumed = 0
  for (const [k, n] of Object.entries(spent)) {
    if (!n || !profile[k]) continue
    const l = lineCost(profile[k], prices, n); lines['done:' + k] = l; spentUsd += l.usd; if (!l.measured) assumed += l.usd
  }
  for (const [k, n] of Object.entries(ahead)) {
    if (!n || !profile[k]) continue
    const l = lineCost(profile[k], prices, n); lines['ahead:' + k] = l; aheadUsd += l.usd; if (!l.measured) assumed += l.usd
  }
  return { lines, spent_usd: +spentUsd.toFixed(2), ahead_usd: +aheadUsd.toFixed(2), assumed_usd: +assumed.toFixed(2) }
}

// ===========================================================================
// src/70-recon.js
// ===========================================================================
// ---------------------------------------------------------------------------
// Probe and Recon: the two lanes that run before anything is designed or built.
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// Probe. One trivial, tool-free call per primary model. An API-key account may
// have an alias disabled for its organisation; a subscription may sit on a plan
// without one of the tiers. Either way the run must learn it here, for cents,
// not after Recon and a spec have been paid for. No fallback: the point is to
// know whether the PRIMARY works. Cached on resume like every other call.
// ---------------------------------------------------------------------------
if (PROBE_MODELS) {
  phase('Probe')
  const probeModels = PRIMARY_MODELS
  const probes = await parallel(probeModels.map((m) => () =>
    agent('Answer with the structured output ok:true. Use no tools, read nothing, run nothing.',
      { label: 'probe:' + m, phase: 'Probe', model: m, effort: 'low', schema: PROBE_SCHEMA })
      .catch((e) => ({ error: String(e.message || e).slice(0, 160) }))))
  const dead = probeModels.filter((m, i) => !probes[i] || probes[i].ok !== true)
  if (dead.length) {
    const detail = probeModels.map((m, i) => m + ': ' + (probes[i] && probes[i].ok === true ? 'ok' : (probes[i] && probes[i].error) || 'returned nothing'))
    log('PROBE FAILED — ' + detail.join(', '))
    return {
      ok: false,
      stage: 'probe',
      error: 'model(s) not usable from this session: ' + dead.join(', ') + '. On an API-key account, check that the model ' +
        'is enabled for the organisation (console.anthropic.com → Settings → Limits/Models) and that ANTHROPIC_API_KEY is the right ' +
        'key; on a subscription, that the plan includes it. Nothing was spent beyond these probes. Pass probeModels:false to skip.',
      probes: Object.fromEntries(probeModels.map((m, i) => [m, probes[i]])),
    }
  }
  log('probe: ' + probeModels.join(' and ') + ' answered')
}

// Every ecosystem names its own verification differently, and the repo — not
// this script — is the authority. This list exists so the recon agent looks in
// the right places instead of assuming Make and npm.
const DISCOVERY_HINTS = [
  'CLAUDE.md, AGENTS.md, CONTRIBUTING.md, README — a stated command always wins over an inferred one.',
  'CI config, which is the most reliable source of the command that must actually pass:',
  '  .gitlab-ci.yml, .github/workflows/*, azure-pipelines.yml, Jenkinsfile, .pre-commit-config.yaml',
  'Task runners: Makefile, justfile, Taskfile.yml, package.json scripts, tox.ini, noxfile.py',
  'Per-ecosystem manifests:',
  '  python      pyproject.toml, setup.cfg, pytest.ini, requirements*.txt (prefer a venv binary if one exists)',
  '  node        package.json (npm/pnpm/yarn test), vitest/jest config',
  '  go          go.mod -> `go test ./...`',
  '  rust        Cargo.toml -> `cargo test`',
  '  java/kotlin pom.xml -> `mvn test`; build.gradle -> `./gradlew test`',
  '  ruby        Gemfile -> `bundle exec rspec`',
  '  php         composer.json -> `composer test`',
  '  dotnet      *.sln/*.csproj -> `dotnet test`',
  '  elixir      mix.exs -> `mix test`',
  '  terraform / opentofu   `terraform validate` / `tofu validate`, `tflint`, `terraform fmt -check`,',
  '              plus `terraform plan` where it runs without credentials or side effects',
  '  k8s/helm    `helm lint`, `kubeconform`, `kustomize build`',
  '  shell       `shellcheck`, `bats`',
  '  sql/dbt     `dbt build --empty`, `sqlfluff lint`',
  '  docs/config `markdownlint`, `yamllint`, JSON schema validation',
].join('\n')

// ---------------------------------------------------------------------------
// Recon. Establishes, ONCE, the three things that used to be either assumed or
// rediscovered N times: that this is a safe git repo to commit into, what the
// repo is, and the exact command that proves the work. Doing it once is both
// cheaper and more consistent — N agents guessing a test command independently
// is N chances to disagree about what "passing" means.
// ---------------------------------------------------------------------------
phase('Recon')
log('task: ' + TASK.slice(0, 160))

const recon = await callAgent(
  [
    'You are RECON. You write no code and make no commits. Establish the ground truth the rest of this run depends on.',
    '',
    'The task that is about to be implemented here, for context only — do NOT start it:',
    TASK_TEXT,
    '',
    '0. TOOLS. Run `git --version`. If git is missing, report is_git_repo:false and say so in dirty_summary.',
    '1. GIT STATE. Run these and report exactly what they say:',
    '   `git rev-parse --is-inside-work-tree`, `git rev-parse HEAD`,',
    '   `git rev-parse --abbrev-ref HEAD`, `git status --porcelain`',
    '   For is_trunk, work out this repo\'s ACTUAL shared trunk rather than assuming a name —',
    '   `git symbolic-ref refs/remotes/origin/HEAD` is the usual answer, and CI config or',
    '   CLAUDE.md may name a different protected branch (some repos protect `develop`, some',
    '   deploy from `main` and develop on `dev`).',
    '',
    '2. WHAT THIS REPO IS. Not every repo is an application with unit tests. It may be',
    '   Terraform/OpenTofu, Helm charts, shell, SQL, docs, or several of those at once.',
    '   Say what it actually is in `ecosystem`.',
    '',
    '3. HOW IT VERIFIES ITSELF. Find every command that can FAIL and thereby prove something. Look here:',
    DISCOVERY_HINTS,
    '',
    '   RUN EXACTLY ONE of them: the one you will name `primary_check_cmd`. Choose the FASTEST command that',
    '   genuinely proves something — a smoke or quick target over the full suite, a real test run over',
    '   validate/lint/build. Run it in the foreground under `timeout 180`; if it does not finish in that time,',
    '   it is not the primary: report it with verified_runs false and "too slow for the run" in `source`, and',
    '   pick a faster one. Every other command is reported with verified_runs false, unexecuted. Never start a',
    '   check in the background, never poll a process, never inspect why a test run is slow: that is not your',
    '   job, and the run you are the first agent of pays for every minute you spend on it. (Measured: a recon',
    '   that ran the full suite and babysat it took 7 minutes and 67 tool calls; the number was never used.)',
    '   A command that needs credentials, network or a running service you do not have is still worth',
    '   reporting — verified_runs false and say why in `source`. If the repo genuinely has nothing',
    '   executable, return an empty string and has_executable_checks:false. That is an honest and useful',
    '   answer — do NOT invent a plausible-looking command.',
    '',
    '4. LAYOUT AND CONVENTIONS. Read CLAUDE.md / AGENTS.md / CONTRIBUTING.md / README.',
    '   Capture anything an implementer would otherwise waste three tool calls rediscovering,',
    '   and quote any hard rules verbatim — especially worktree requirements, commit message',
    '   or trailer rules, and files that must not be touched.',
    '',
    '5. DATE AND DOCUMENTS. Run `date -I` and report it as `today`. Look for where this repo keeps',
    '   design specs and implementation plans (docs/specs, docs/plans, docs/superpowers/…, a docs/',
    '   README) and how the most recent ones are named; report that in `docs_layout`, or empty.',
    (FROM === 'idea'
      ? [
        '',
        '6. WHERE THE TASK LANDS, AND WHAT THE OWNER MUST DECIDE. The task above is an idea; a spec',
        '   writer reads your answer next and starts from it instead of rediscovering the repo.',
        '   `touchpoints`: grep for the names, routes, tables, flags and modules the idea mentions and',
        '   list the files it will have to read or change — the entry point it extends, the module it',
        '   changes, the tests that cover it, the config it reads, and any SECOND caller or UI the',
        '   change must reach — each with a line range measured with `grep -n` and one line on why it',
        '   matters. Five to fifteen entries, measured on the current tree, never guessed; empty only',
        '   when the idea is genuinely greenfield.',
        '   `owner_questions`: the questions a careful colleague would put to the owner BEFORE',
        '   designing this — only where a choice affects money, risk, data, ownership, reverses',
        '   something that exists, or is one careful colleagues would make differently. Two to four',
        '   options each, the consequence of each, your recommendation and why. The engine asks the',
        '   owner before the spec is written. Most ideas have zero or one such question; never ask',
        '   what the idea already states, and never ask what a careful colleague would decide alone.',
      ].join('\n')
      : ''),
  ].join('\n'),
  { label: 'recon', phase: 'Recon', model: CODER, effort: EFFORT, schema: RECON_SCHEMA }
)

if (!recon) {
  return { ok: false, stage: 'recon', error: 'recon agent returned nothing; cannot establish repo state' }
}
if (recon.is_git_repo !== true) {
  return {
    ok: false,
    stage: 'recon',
    error: 'not a git repository (or git is not installed — recon ran `git --version`; see dirty_summary). Every lane here commits and diffs, so a repo is required. Run `git init` and make a first commit, or launch from inside the repo.',
    recon: recon,
  }
}
if (!String(recon.head_sha || '').trim()) {
  return {
    ok: false,
    stage: 'recon',
    error: 'repo has no commits yet, so there is no base to diff against. Make an initial commit first.',
    recon: recon,
  }
}
if (recon.dirty === true && !ALLOW_DIRTY) {
  return {
    ok: false,
    stage: 'recon',
    error: 'working tree is dirty. Several agents commit concurrently and the adversary reviews the combined diff, so pre-existing changes would be attributed to this run. Commit or stash first, or pass allowDirty:true if the changes are genuinely part of the task.',
    dirty_summary: recon.dirty_summary || '',
    recon: recon,
  }
}
if (recon.is_trunk === true && !ALLOW_TRUNK) {
  return {
    ok: false,
    stage: 'recon',
    error: 'refusing to run on `' + (recon.branch || '?') + '`, which this repo treats as its shared trunk. Several agents commit concurrently; that must not land on a trunk. Create a branch (or a worktree) and relaunch, or pass allowTrunk:true.',
    recon: recon,
  }
}

const BASE = String(recon.head_sha).trim()
const CHECK_CMD = TEST_CMD || String(recon.primary_check_cmd || '').trim()
// An explicit testCmd always wins, including over Recon's has_executable_checks:false —
// the caller said it runs, and the adversary will find out if it does not.
const HAS_CHECKS = TEST_CMD ? true : Boolean(CHECK_CMD) && recon.has_executable_checks !== false

const TEST_LINE = CHECK_CMD
  ? 'The command that proves this repo still works is: ' + CHECK_CMD +
  (TEST_CMD ? ' (supplied by the caller — prefer it over anything you discover).' : ' (found by recon; if it is wrong, say so rather than silently substituting your own).')
  : 'Recon found NOTHING executable in this repo (' + (recon.ecosystem || 'unknown ecosystem') + '). Do not invent a command. ' +
  'Verification here is necessarily read-only: say so plainly instead of implying you ran something.'

log('repo: ' + (recon.ecosystem || 'unknown') + ' on ' + (recon.branch || '?') +
  ' @ ' + BASE.slice(0, 8) + (HAS_CHECKS ? ' | check: ' + CHECK_CMD : ' | NO EXECUTABLE CHECKS'))
if (!HAS_CHECKS) {
  log('WARNING: nothing executable to run. Review degrades to reading the diff; ' +
    'treat a clean verdict as weaker evidence than usual.')
}
if (Array.isArray(recon.verify_commands) && recon.verify_commands.length > 1) {
  log('other checks available: ' + recon.verify_commands.slice(1).map((c) => c.kind + '=' + c.command).join(' | '))
}

// ===========================================================================
// src/80-documents.js
// ===========================================================================
// ---------------------------------------------------------------------------
// The documents. Today's date and the docs layout come from Recon (the engine
// has no clock). A document writer WRITES and COMMITS its file; a reviewer is
// read-only and returns findings with evidence; a fold-in agent judges each
// finding, edits the document, commits, and returns what it folded and what it
// refuted. One review round per document by default (docRounds).
// ---------------------------------------------------------------------------
const TODAY = /^\d{4}-\d{2}-\d{2}$/.test(String(recon.today || '')) ? String(recon.today) : 'undated'
if (TODAY === 'undated') log('WARNING: recon did not report today\'s date; documents will be named undated-<slug>.md — rename them before merging')
const DOCS_LAYOUT = String(recon.docs_layout || '').trim()
const SPEC_DIR = SPEC_DIR_IN || (/(docs\/[\w./-]*specs)/.exec(DOCS_LAYOUT) || [null, 'docs/specs'])[1]
const PLANS_DIR = PLANS_DIR_IN || (/(docs\/[\w./-]*plans)/.exec(DOCS_LAYOUT) || [null, 'docs/plans'])[1]
const COMMIT_RULES = 'Commit in this repo\'s own convention' + (recon.conventions ? ' (its stated conventions: ' + recon.conventions.slice(0, 1500) + ')' : '') + '. Do NOT push.'

const documents = { from: FROM, spec: null, spec_reviews: [], plan: null, plan_reviews: [], decisions: [], questions: [], answers: ANSWERS }
// Declared here, before the helpers that read them, so a pause at the spec stage can
// report both without tripping over a `let` further down that has not run yet.
let SPEC_PATH = SPEC_PATH_IN || (FROM === 'spec' && looksLikePath(TASK) ? TASK.trim() : '')
let PLAN_PATH = PLAN_PATH_IN || (FROM === 'plan' && looksLikePath(TASK) ? TASK.trim() : '')
let planDoc = null
let planReindexed = false

// The runtime phase a document lane reports under.
function docPhase(kind) {
  return kind === 'spec' ? 'Spec review' : 'Plan review'
}

// The documents block every early return and the final report carry.
function documentsReport() {
  return { ...documents, spec_path: SPEC_PATH || null, plan_path: PLAN_PATH || null }
}

// Told to both document writers when the run will not pause for the owner.
const OWNER_NOT_ASKED_NOTE = PAUSE_FOR_OWNER ? '' : '- THE OWNER WILL NOT BE ASKED in this run (pauseForOwner:false). Still list such questions in\n' +
  '  `open_questions` with your recommendation, but write the recommended option into the document as the\n' +
  '  decision, marked "(recommended option; owner not asked)" — never "pending owner".'

function answersFor(stage) {
  return ANSWERS.filter((a) => a.id.startsWith(stage + ':') && a.answer.trim())
}

// Returns null to continue, or the early-return object when the run must pause.
function ownerGate(stage, questions, docPath) {
  const answered = new Set(answersFor(stage).map((a) => a.id))
  const open = questions.filter((q) => !answered.has(q.id))
  documents.questions.push(...questions.map((q) => ({ ...q, answered: answered.has(q.id) })))
  if (!open.length) return null
  if (!PAUSE_FOR_OWNER) {
    log(stage + ': ' + open.length + ' owner question(s) left to the recommended option (pauseForOwner:false): ' +
      open.map((q) => q.id + ' -> ' + q.recommended).join(', '))
    documents.decisions.push(...open.map((q) => ({
      stage: stage, question: q.question, decision: q.recommended + ' (recommended option, owner not asked)', why: q.why,
    })))
    return null
  }
  log('PAUSED at the ' + stage + ' stage: ' + open.length + ' question(s) for the owner — ' + open.map((q) => q.id).join(', '))
  return {
    ok: true,
    paused: true,
    stage: stage,
    questions: open,
    document: docPath,
    how_to_resume: 'Ask the user each question (recommended option first), then relaunch this workflow with the SAME script ' +
      'and resumeFromRunId, and args identical except `answers`: [{id, answer}] for every question above ' +
      '(keep earlier answers too). Every agent before this pause replays from cache.',
    answers_so_far: ANSWERS,
    documents: documentsReport(),
    recon: recon,
  }
}

async function applyAnswers(stage, docPath, questions) {
  const given = answersFor(stage)
  if (!given.length) return null
  const byId = Object.fromEntries(questions.map((q) => [q.id, q]))
  const applied = await callAgent(
    [
      'You are the AUTHOR recording the OWNER\'S ANSWERS in your ' + stage + ': ' + docPath,
      '',
      'THE OWNER ANSWERED THESE QUESTIONS (the owner outranks every reviewer and every provisional decision):',
      JSON.stringify(given.map((a) => ({ id: a.id, question: (byId[a.id] || {}).question || '', answer: a.answer,
        options: (byId[a.id] || {}).options || [] })), null, 2),
      '',
      'DO THIS:',
      '- For each answer, find the provisional decision marked "pending owner" and REPLACE it with the owner\'s',
      '  decision, attributed to the owner. Where the owner picked a listed option, apply that option\'s',
      '  consequence throughout the document (scope, behaviour, data, tests, out-of-scope lists). Where the',
      '  owner wrote something else, treat it as the decision and reshape the affected sections to match.',
      '- Keep the document whole and consistent afterwards; no placeholder may survive.',
      '- Record every answer in the "Decisions taken without the owner" table\'s neighbour: a table titled',
      '  "Decisions taken by the owner" (question, decision, date ' + TODAY + ').',
      '- ' + COMMIT_RULES,
    ].join('\n'),
    { label: stage + '-answers', phase: docPhase(stage), model: DOC_JUDGE, effort: EFFORT, schema: FOLD_SCHEMA }
  )
  // The owner's answer goes on the record only once an author has written it into the
  // document; an author that returned nothing leaves "pending owner" in the text, and
  // claiming the decision recorded would be the lie the record exists to prevent.
  if (!applied) return false
  documents.decisions.push(...given.map((a) => ({
    stage: stage, question: (byId[a.id] || {}).question || a.id, decision: a.answer, why: 'the owner\'s answer',
  })))
  return applied
}

function answersLost(stage, docPath) {
  return { ok: false, stage: stage, error: 'the author recording the owner\'s answers in the ' + stage + ' returned nothing after its fallback; ' +
    docPath + ' still carries the provisional decisions marked "pending owner". Relaunch with the same answers.',
    recon, documents: documentsReport(), lane_errors: laneErrors }
}

// A document review round whose reviewer or fold-in author returned nothing is a gate
// that never ran. The build must not proceed on a document nobody attacked (or on
// findings nobody folded in), so the run stops here; a relaunch replays what ran.
function docLaneLost(kind, rounds) {
  const lost = rounds.find((r) => r.lost)
  if (!lost) return null
  const what = lost.why
    ? 'the ' + kind + ' review of round ' + lost.round + ' never reached the document: ' + lost.why + '; '
    : 'the ' + kind + ' ' + lost.lost + ' of round ' + lost.round + ' returned nothing after its fallback; '
  return { ok: false, stage: kind + '-review', error: what +
    'the ' + kind + ' is committed but ' + (lost.lost === 'reviewer' ? 'unreviewed' : 'its review is not folded in') + '. Nothing was sliced or implemented. Relaunch to retry.',
    recon, documents: documentsReport(), lane_errors: laneErrors }
}

async function reviewAndFold(kind, docPath, extra, writerSha) {
  // kind: 'spec' | 'plan'. Returns the list of {review, fold, edit} rounds; `fold` is derived
  // from the same agent's dispositions so the consumers keep their shape.
  const out = []
  let priorSha = String(writerSha || '')
  for (let r = 1; r <= DOC_ROUNDS; r++) {
    phase(docPhase(kind))
    const review = await callAgent(
      [
        'You are the ADVERSARIAL REVIEWER of a ' + (kind === 'spec' ? 'design spec' : 'implementation plan') +
        ', and then its EDITOR. First refute the claim that it is complete, consistent and ready for the next',
        'stage; then EDIT THE DOCUMENT YOURSELF to fold in what held, and commit. Findings you only list are not',
        'a review: the next stage reads the file, not your report. A clean verdict you cannot defend is worse',
        'than a false alarm; a finding without evidence is noise.',
        '',
        'THE DOCUMENT: ' + docPath + ' — read it whole.',
        (extra || ''),
        '',
        'THE REPO: ' + (recon.ecosystem || 'unknown') + (HAS_CHECKS ? '. Check command: ' + CHECK_CMD : '. No executable checks.'),
        (recon.conventions ? 'Conventions it documents, which a violation of IS a finding:\n' + recon.conventions : ''),
        '',
        (kind === 'spec'
          ? [
            'PART 1 — REVIEW. WHAT TO CHECK (the superpowers spec reviewer, sharpened):',
            '- Completeness: TODOs, placeholders, TBDs, incomplete sections, a decision the document dodges.',
            '- Consistency: internal contradictions, conflicting requirements, an architecture that does not match the features.',
            '- Clarity: a requirement ambiguous enough that someone would build the wrong thing.',
            '- Scope: focused enough for ONE plan; unrequested features; over-engineering (YAGNI); and the other',
            '  direction — a place the change must reach that the spec forgot (a second UI, a second caller, a report).',
            '- Reality: does the spec\'s account of the CURRENT code match the tree? Open the files it names and',
            '  check every claim about them. A spec built on a wrong reading of the code produces a wrong plan.',
            '- The "Decisions taken without the owner" section: is every decision there defensible, and is',
            '  any decision hidden elsewhere in the text without being listed?',
            'Calibration: flag only what would cause a flawed plan. Wording, style and "less detailed than',
            'other sections" are not findings.',
          ].join('\n')
          : [
            'PART 1 — REVIEW. WHAT TO CHECK (the superpowers plan reviewer, sharpened by what plan reviews caught):',
            '- Completeness: TODOs, placeholders, incomplete tasks, missing steps, "similar to Task N".',
            '- Spec alignment: every spec requirement maps to a task; no major scope creep; every "Global',
            '  Constraint" copied verbatim from the spec.',
            '- Buildability against the REAL tree, BY READING AND COMPILING — this is where plan reviews earn their keep:',
            '    * every `Modify: path:lines` range: open the file and check the range holds the code the task edits;',
            '    * every fenced code block: parse/compile it where the language allows (`python -m py_compile`,',
            '      `node --check`, `tofu validate` … on a copy in a temp file); a block shown in context may need a wrapper — say which;',
            '    * every test the plan gives: do the fixtures, helpers and imports it uses exist (grep them)? would its',
            '      Step 2 really fail red for the stated reason, and its Step 4 really go green?',
            '    * every Consumes/Produces signature: does the name defined in one task match its use in another?',
            '    * the file-overlap table: does it match every task\'s Files list? are the chains short?',
            '  DO NOT run the test suite, a task\'s tests, or the check command, and do NOT create a worktree or',
            '  splice a task in. Every task is implemented a phase later by a fresh agent that runs its tests red',
            '  and green for real, and a reviewer then re-runs the check on the whole; a test run here is paid',
            '  twice. (Measured: a plan review that spliced tasks into a worktree took 22 minutes and 77 tool calls;',
            '  its findings were ones the implementers would have hit in their own red-green cycle.)',
            '- Task decomposition: clear boundaries; steps actionable; a test cycle per task.',
            '- Sequencing: tasks in an order where each one\'s Consumes already exists.',
            'Calibration: flag only what would cause an implementer to build the wrong thing or get stuck.',
          ].join('\n')),
        '',
        DOCTRINE_REVIEW_CALIBRATION,
        'REVIEW RULES:',
        '- Every finding carries EVIDENCE: the command you ran and what it printed, the file:line you read, the',
        '  two sentences that contradict each other. Under uncertainty, raise it — you will verify it yourself',
        '  in Part 2 before it changes anything; a false negative costs a build.',
        '- status "approved" ONLY if you read the whole document and found nothing meeting that bar; then Part 2',
        '  and Part 3 are empty, and commit_sha and document_diff_stat are empty.',
        '- A decision the document took that the OWNER should make (money, risk, data, ownership, a reversal',
        '  of something that exists, a choice careful colleagues would make differently) is not a finding —',
        '  put it in `questions_for_owner` with options, consequences and your recommendation. ' +
        (PAUSE_FOR_OWNER
          ? 'The run pauses and asks. Do not raise a question the document already lists as one.'
          : 'The owner will NOT be asked in this run: write your recommended option into the document as the\n' +
            '  decision, marked "(recommended option; owner not asked)". Do not raise a question the document already lists.'),
        '',
        'PART 2 — FOLD IN. ' + DOCTRINE_RECEIVING,
        'FOLD-IN RULES:',
        '- Take your findings one at a time. VERIFY each against the document and the tree again before you act:',
        '  a finding that does not survive its own verification is `withdrawn` with the evidence in `changed`,',
        '  and the text is left as it was. Fold in the rest and say in `changed` what changed.',
        '- "Folded" means YOU edited ' + docPath + ' with your file-editing tools so that it now says the fix. A',
        '  finding marked folded whose text is unchanged in the file is a false report, not a fold-in.',
        '- The owner\'s recorded decisions (' + (kind === 'spec' ? 'the "Decisions taken without the owner" and "Decisions taken by the owner" sections' : 'the spec\'s decisions, which the plan must not silently reverse') + ')',
        '  outrank you. A finding that would reverse one is `withdrawn` on that ground, and says so.',
        '- Keep the document whole and consistent after every fold-in: file map, overlap table, self-review,',
        '  line ranges (re-measure them), test names. No placeholders may appear as a result of a fold-in.',
        '- Fix only what a finding names. A fold-in is not a rewrite: do not restructure, re-scope or polish',
        '  sections no finding touches.',
        '- Append a "## Fold-in record (review round ' + r + ')" section: a table of every finding id, severity,',
        '  disposition (folded / withdrawn) and what changed or why not.',
        '- ' + COMMIT_RULES + ' Report the commit in commit_sha.',
        '',
        'PART 3 — PROVE IT. Run `git show --stat <commit_sha> -- ' + docPath + '` and paste its output in',
        '`document_diff_stat`; it must list the document. The engine checks this: a review with findings and no',
        'new commit touching the document gets an editor sent after it, and if that fails too the run stops',
        'before anything is built.',
        (r > 1 ? '\nThis is review round ' + r + '; the fold-in of round ' + (r - 1) + ' is already in the file.' : ''),
      ].join('\n'),
      { label: kind + '-review:r' + r, phase: docPhase(kind), model: DOC_JUDGE, effort: EFFORT, schema: DOC_REVIEW_SCHEMA }
    )
    if (!review) { out.push({ round: r, review: null, fold: null, lost: 'reviewer' }); break }
    const findings = Array.isArray(review.findings) ? review.findings : []
    const folded = findings.filter((f) => f.disposition === 'folded')
    const withdrawn = findings.filter((f) => f.disposition !== 'folded')
    let commitSha = review.commit_sha || ''
    let edit = null
    const unproven = docEditUnproven(findings.length, commitSha, review.document_diff_stat, docPath, priorSha)
    if (unproven) {
      log('WARNING: the ' + kind + ' reviewer of round ' + r + ' ' + unproven + ' — sending an editor to write its ' + findings.length + ' finding(s) into ' + docPath)
      edit = await callAgent(
        [
          'You are the EDITOR of ' + docPath + '. Its adversarial reviewer (review round ' + r + ') reported the findings',
          'below with their dispositions, but it ' + unproven + '. The review is not done until the document says it.',
          '',
          'THE FINDINGS (already verified by the reviewer; do not re-litigate a disposition):',
          JSON.stringify(findings, null, 2),
          '',
          'DO THIS:',
          '- Open ' + docPath + ' as it stands now. For every `folded` finding, EDIT THE FILE so it says what the',
          '  finding\'s `fix` and `changed` say. Where the edit is already in the file, leave it.',
          '- Keep the document whole and consistent: file map, overlap table, self-review, line ranges (re-measure',
          '  them), test names. Change nothing no finding names.',
          '- Make sure a "## Fold-in record (review round ' + r + ')" section lists every finding id, severity,',
          '  disposition (folded / withdrawn) and what changed or why it was withdrawn.',
          '- ' + COMMIT_RULES,
          '- Then run `git show --stat <your commit> -- ' + docPath + '` and paste its output in `document_diff_stat`;',
          '  it must list the document.',
        ].join('\n'),
        { label: kind + '-edit:r' + r, phase: docPhase(kind), model: DOC_JUDGE, effort: EFFORT, schema: EDIT_SCHEMA }
      )
      const still = edit ? docEditUnproven(findings.length, edit.commit_sha, edit.document_diff_stat, docPath, priorSha) : 'returned nothing after its fallback'
      if (still) {
        out.push({ round: r, review, fold: null, edit, lost: 'editor', why: 'the reviewer ' + unproven + ', and the editor sent after it ' + still })
        break
      }
      commitSha = edit.commit_sha
    }
    if (commitSha) priorSha = commitSha
    // The same agent's dispositions, in the shape the earlier two-lane design reported.
    const fold = findings.length
      ? { folded: folded.map((f) => f.id), refuted: withdrawn.map((f) => ({ id: f.id, evidence: f.changed || 'withdrawn without a reason' })),
        commit_sha: commitSha, summary: review.summary }
      : null
    log(kind + ' review round ' + r + ': ' + review.status + ', ' + findings.length + ' finding(s)' +
      (findings.length ? ' — ' + folded.length + ' folded, ' + withdrawn.length + ' withdrawn @ ' + String(commitSha).slice(0, 8) + (edit ? ' (by the editor)' : '') : ''))
    out.push({ round: r, review, fold, edit })
    // A fold-in is a decision too: the reviewer changed the document on its own finding, or
    // withdrew it. Both go on the record, so the owner can overturn either.
    for (const f of folded) {
      documents.decisions.push({ stage: kind + '-fold', question: 'Review finding ' + f.id + (f.claim ? ': ' + f.claim : ''),
        decision: 'folded in' + (f.changed ? ': ' + f.changed : f.fix ? ': ' + f.fix : ''), why: f.evidence ? 'reviewer\'s evidence: ' + f.evidence : 'the finding held' })
    }
    for (const f of withdrawn) {
      documents.decisions.push({ stage: kind + '-fold', question: 'Review finding ' + f.id + (f.claim ? ': ' + f.claim : ''),
        decision: 'withdrawn; document left as it was', why: f.changed || 'no reason given' })
    }
    if (review.status === 'approved' || findings.length === 0) break
  }
  return out
}

// The owner's decisions a writer starts with, in the shape the writer must record. Answers
// come from the resume (the questions Recon raised before the spec existed); with
// pauseForOwner:false the recommended options stand and the writer is told so. Empty when
// there is nothing to record.
function ownerDecisionsBlock(stage, questions) {
  const byId = Object.fromEntries((questions || []).map((q) => [q.id, q]))
  const given = answersFor(stage)
  const lines = []
  if (given.length) {
    lines.push(
      'THE OWNER HAS ALREADY ANSWERED THESE QUESTIONS (binding; the owner outranks every reviewer and every',
      'provisional decision). Write each into the document as the decision, attributed to the owner, in a table',
      'titled "Decisions taken by the owner" (question, decision, date ' + TODAY + '), and apply its consequence',
      'throughout. Never re-raise one of them:',
      JSON.stringify(given.map((a) => ({ id: a.id, question: (byId[a.id] || {}).question || '', answer: a.answer,
        options: (byId[a.id] || {}).options || [] })), null, 2),
    )
  }
  if (!PAUSE_FOR_OWNER) {
    const answered = new Set(given.map((a) => a.id))
    const standing = (questions || []).filter((q) => !answered.has(q.id))
    if (standing.length) {
      lines.push(
        'THESE QUESTIONS WERE RAISED BEFORE YOU AND THE OWNER WAS NOT ASKED (pauseForOwner:false); the recommended',
        'option stands. Write each into the document as the decision, marked "(recommended option; owner not',
        'asked)", and do not raise it again:',
        JSON.stringify(standing.map((q) => ({ id: q.id, question: q.question, recommended: q.recommended, why: q.why })), null, 2),
      )
    }
  }
  return lines.join('\n')
}

// Recon's map of where the idea lands, as a list the writer reads before it explores.
function touchpointsBlock(points) {
  const list = (Array.isArray(points) ? points : []).filter((t) => t && t.path)
  if (!list.length) return ''
  return [
    'WHERE THE TASK LANDS (measured by Recon on the current tree). Start here: read these, cite what you read,',
    'and explore beyond them only where they run out. A file listed here that the spec does not mention needs a',
    'reason in the spec.',
    ...list.map((t) => '- ' + t.path + (t.lines ? ':' + t.lines : '') + ' — ' + (t.why || '')),
  ].join('\n')
}

// ----- Spec ---------------------------------------------------------------
if (FROM === 'idea') {
  // The questions Recon raised are the owner's before a word of the spec is written: the
  // writer then designs with the answers in hand instead of around a provisional decision
  // the reviewer has to fold around and an author has to rewrite after the pause.
  const ideaQuestions = namespaced('idea', recon.owner_questions || [])
  const pauseIdea = ownerGate('idea', ideaQuestions, null)
  if (pauseIdea) return pauseIdea
  phase('Spec')
  const spec = await callAgent(
    [
      'You are the SPEC WRITER. Turn the idea below into a design spec, write it to a file, and commit it.',
      'You write no implementation code.',
      '',
      'THE IDEA:',
      TASK,
      '',
      'THE REPO: ' + (recon.ecosystem || 'unknown') + ' on branch ' + (recon.branch || '?') + '.',
      (recon.layout_notes ? 'Layout: ' + recon.layout_notes : ''),
      (recon.conventions ? 'Conventions (binding): ' + recon.conventions : ''),
      (DOCS_LAYOUT ? 'Documents convention: ' + DOCS_LAYOUT : ''),
      '',
      touchpointsBlock(recon.touchpoints),
      '',
      ownerDecisionsBlock('idea', ideaQuestions),
      '',
      DOCTRINE_BRAINSTORM,
      'OUTPUT:',
      '- Write the spec to `' + SPEC_DIR + '/' + TODAY + '-<slug>.md` (follow the repo\'s naming where it has one).',
      '- Structure it so a plan can be written from it alone: the problem and the evidence for it in the',
      '  current code (cite files and lines you actually read), the decisions, the required behaviour with',
      '  numbered sections, the claims a test can make, the effect on existing data, risks, out of scope, and',
      '  the "Decisions taken without the owner" table.',
      '- Any constraint from the repo (principles in CLAUDE.md, module budgets, one-writer rules, channel',
      '  rules) that this work touches is restated in the spec, verbatim, as a hard constraint.',
      '- QUESTIONS FOR THE OWNER: the doctrine above says decide and record. One exception. When a choice',
      '  affects money, risk, data, ownership, reverses something that exists, or is one careful colleagues',
      '  would make differently, do NOT decide it silently: put it in `open_questions` with two to four',
      '  options, the consequence of each, and your recommendation with its reason; write the recommended',
      '  option into the spec as the provisional decision, marked "pending owner", so the document is',
      '  complete either way. The run will pause and ask the owner. Everything below that bar, decide.',
      '  A question the owner has already answered above is settled: never raise it again.',
      OWNER_NOT_ASKED_NOTE,
      '- ' + COMMIT_RULES,
    ].join('\n'),
    { label: 'spec', phase: 'Spec', model: DOC_WRITER, effort: EFFORT, schema: SPEC_SCHEMA }
  )
  if (!spec) return { ok: false, stage: 'spec', error: 'the spec writer returned nothing', recon }
  SPEC_PATH = spec.path
  documents.spec = spec
  documents.decisions.push(...(spec.decisions || []).map((d) => ({ stage: 'spec', ...d })))
  log('spec: ' + spec.path + ' (' + spec.classification + ', ' + (spec.decisions || []).length + ' decision(s) taken without the owner)')
  documents.spec_reviews = await reviewAndFold('spec', SPEC_PATH, 'THE IDEA IT CAME FROM:\n' + TASK, spec.commit_sha)
  const specLost = docLaneLost('spec', documents.spec_reviews)
  if (specLost) return specLost
  const specQuestions = namespaced('spec', [
    ...(spec.open_questions || []),
    ...documents.spec_reviews.flatMap((r) => (r.review && r.review.questions_for_owner) || []),
  ])
  const pause = ownerGate('spec', specQuestions, SPEC_PATH)
  if (pause) return pause
  const applied = await applyAnswers('spec', SPEC_PATH, specQuestions)
  if (applied === false) return answersLost('spec', SPEC_PATH)
  if (applied) log('spec: owner answers recorded (' + (applied.commit_sha || 'no commit') + ')')
}

// ----- Plan ---------------------------------------------------------------
if (FROM === 'idea' || FROM === 'spec') {
  phase('Plan')
  const specRef = SPEC_PATH ? 'THE SPEC: ' + SPEC_PATH + ' — read it whole; the plan argues from it.' : 'THE SPEC (inline):\n' + TASK
  planDoc = await callAgent(
    [
      'You are the PLAN WRITER. Write the implementation plan for the spec below, to a file, and commit it.',
      'You write no implementation code — but every code block the plan gives must be real, complete code,',
      'measured against the CURRENT tree.',
      '',
      specRef,
      (answersFor('idea').length || answersFor('spec').length
        ? '\nTHE OWNER\'S ANSWERS to the questions raised before and by the spec (binding; already written into the spec):\n' +
          JSON.stringify([...answersFor('idea'), ...answersFor('spec')], null, 2)
        : ''),
      '',
      'THE REPO: ' + (recon.ecosystem || 'unknown') + ' on branch ' + (recon.branch || '?') + '.',
      (HAS_CHECKS ? 'Check command: ' + CHECK_CMD : 'No executable checks — say so in Global Constraints.'),
      (recon.layout_notes ? 'Layout: ' + recon.layout_notes : ''),
      (recon.conventions ? 'Conventions (binding): ' + recon.conventions : ''),
      (DOCS_LAYOUT ? 'Documents convention: ' + DOCS_LAYOUT : ''),
      '',
      DOCTRINE_WRITING_PLANS,
      'HOW THIS PLAN WILL BE EXECUTED, which shapes it:',
      '- One task = one slice = one fresh implementer agent that reads ONLY its task section, the Global',
      '  Constraints and a short shared context. So a task must be complete in itself: files with measured',
      '  line ranges, exact Consumes/Produces, the failing test as real code, the implementation as real code,',
      '  the exact commands, the commit message.',
      '- Tasks that touch a common file run one after another. Keep such chains at four or fewer; merge',
      '  where a chain would be longer. Prefer tasks that are file-disjoint.',
      '- A different model then reads the whole diff, re-runs the repo\'s check and attacks the work against',
      '  this plan, task by task. Write the plan so that judge has something exact to hold the work to.',
      '',
      'OUTPUT:',
      '- Write to `' + PLANS_DIR + '/' + TODAY + '-<slug>.md`' + (SPEC_PATH ? ' (same slug as the spec).' : '.'),
      '- ' + COMMIT_RULES,
      '- Report every task with its files and its line range in the file AFTER your final edit (grep -n).',
      '- Report in `decisions` every call the plan makes that the spec left open or that narrows it — a',
      '  declared narrowing, a migration number, an ordering, a file boundary — and write the same list into',
      '  the plan under a "## Decisions taken by the plan" heading. A narrowing hidden in a task body is the',
      '  kind of decision an owner discovers only after the build.',
      '- QUESTIONS FOR THE OWNER: a sequencing or scoping choice that affects money, risk, data, ownership,',
      '  reverses something that exists, or is one careful colleagues would make differently (a destructive',
      '  migration step, an ordering that deletes before it copies) is NOT yours to take silently: put it in',
      '  `open_questions` with two to four options, the consequence of each, and your recommendation; write the',
      '  recommended option into the plan as the provisional decision, marked "pending owner". The run pauses',
      '  and asks. Everything below that bar, decide and record.',
      OWNER_NOT_ASKED_NOTE,
    ].join('\n'),
    { label: 'plan-doc', phase: 'Plan', model: DOC_WRITER, effort: EFFORT, schema: PLANDOC_SCHEMA }
  )
  if (!planDoc) return { ok: false, stage: 'plan', error: 'the plan writer returned nothing', recon, documents }
  PLAN_PATH = planDoc.path
  documents.plan = planDoc
  documents.decisions.push(...(planDoc.decisions || []).map((d) => ({ stage: 'plan', ...d })))
  log('plan: ' + planDoc.path + ' (' + planDoc.tasks.length + ' task(s), ' + (planDoc.decisions || []).length + ' decision(s))')
  documents.plan_reviews = await reviewAndFold('plan', PLAN_PATH, (SPEC_PATH ? 'THE SPEC IT IMPLEMENTS: ' + SPEC_PATH : 'THE REQUIREMENTS:\n' + TASK), planDoc.commit_sha)
  const planLost = docLaneLost('plan', documents.plan_reviews)
  if (planLost) return planLost
  const planQuestions = namespaced('plan', [
    ...(planDoc.open_questions || []),
    ...documents.plan_reviews.flatMap((r) => (r.review && r.review.questions_for_owner) || []),
  ])
  const pausePlan = ownerGate('plan', planQuestions, PLAN_PATH)
  if (pausePlan) return pausePlan
  const appliedPlan = await applyAnswers('plan', PLAN_PATH, planQuestions)
  if (appliedPlan === false) return answersLost('plan', PLAN_PATH)
  if (appliedPlan) log('plan: owner answers recorded (' + (appliedPlan.commit_sha || 'no commit') + ')')
  planReindexed = documents.plan_reviews.some((r) => r.fold && r.fold.commit_sha) || Boolean(appliedPlan && appliedPlan.commit_sha)
}

// There is no consolidated decision recorder (removed 2026-09-12: a 6-minute Sonnet lane
// that re-wrote 45 decisions already present in the documents' own tables — the spec
// writer's, the plan writer's, each fold-in record and the owner's answers). Every
// decision is still in `documents.decisions`, in order, and in the documents themselves.
// Line ranges move under a fold-in and an answers commit, and the slicer hands them to
// implementers as pointers — so the plan is measured once, AFTER the last agent that
// wrote into it (a 25-second Sonnet call). The plan writer's decisions stay on the record.
if (planReindexed && planDoc) {
  const remeasured = await callAgent(
    [
      'Read ' + PLAN_PATH + ' as it stands NOW and report every "### Task N" section in order with its files',
      'and its line range (grep -n "^### Task" and "^## Global Constraints"; the range ends where the next',
      'section starts). Report the commit_sha as `git rev-parse HEAD`. Do not edit anything.',
    ].join('\n'),
    { label: 'plan-index', phase: 'Plan review', model: CODER, effort: 'low', schema: PLANDOC_SCHEMA }
  )
  if (remeasured) { planDoc = { ...remeasured, decisions: planDoc.decisions || [], open_questions: planDoc.open_questions || [] }; documents.plan = planDoc }
}

// ===========================================================================
// src/90-slice.js
// ===========================================================================
// ---------------------------------------------------------------------------
// Slice — the plan's tasks become file-disjoint slices.
// ---------------------------------------------------------------------------
phase('Slice')

const PLAN_INDEX = planDoc
  ? 'THE PLAN DOCUMENT: ' + PLAN_PATH + '\nGlobal Constraints at lines ' + (planDoc.global_constraints_lines || '?') +
    '\nTASKS (one slice each unless a chain must be merged):\n' +
    planDoc.tasks.map((t) => '  Task ' + t.n + ' — ' + t.title + ' — files: ' + (t.files || []).join(', ') + ' — lines ' + t.lines).join('\n')
  : (PLAN_PATH ? 'THE PLAN DOCUMENT: ' + PLAN_PATH + ' — read it and index its tasks yourself.' : '')

// The orchestrator's slices go to the implementers as given: the five fields the slicer
// would have returned, nothing invented on top. uncovered stays empty — scope the
// orchestrator left out is theirs to know, not a slicer's admission.
let plan
if (SLICES_IN) {
  plan = {
    shared_context: SHARED_CONTEXT_IN,
    task_summary: TASK_SUMMARY_IN,
    slices: SLICES_IN.map((s) => ({
      id: String(s.id).trim(), title: String(s.title).trim(), prompt: String(s.prompt).trim(),
      files: (s.files || []).map((f) => String(f).trim()), done_when: String(s.done_when).trim(),
    })),
    uncovered: [],
    notes: [],
  }
  log('slices: ' + plan.slices.length + ' from the orchestrator — no slicer lane')
} else {
  plan = await callAgent(
  [
    'You are the SLICER. You do not write the implementation — you map the plan\'s tasks onto slices so that several implementers can work at once without colliding.',
    '',
    'TASK:',
    TASK_TEXT,
    '',
    PLAN_INDEX,
    '',
    'WHAT RECON ALREADY ESTABLISHED — trust this and do not re-derive it:',
    JSON.stringify({
      ecosystem: recon.ecosystem,
      branch: recon.branch,
      base_sha: BASE,
      check_command: CHECK_CMD || null,
      has_executable_checks: HAS_CHECKS,
      other_checks: (recon.verify_commands || []).slice(1),
      layout_notes: recon.layout_notes,
      conventions: recon.conventions,
    }, null, 2),
    '',
    'Do this:',
    '1. Read enough of the repo to plan honestly, building on the recon notes above rather than repeating that work.',
    '   FOLLOW whatever conventions CLAUDE.md / AGENTS.md state.',
    '2. Split the work into at most ' + MAX_SLICES + ' slices. When a plan document is given, ONE TASK = ONE SLICE',
    '   in the plan\'s order, each slice prompt pointing at its task section by path + heading + line range; the',
    '   only reshaping allowed is merging adjacent tasks of a serial chain longer than four.',
    '',
    'The one rule that matters: SLICES MUST BE FILE-DISJOINT. Two slices that touch the same file are run one',
    'after the other instead of at the same time. They each keep their own fresh agent, so the',
    'only thing overlap costs is wall-clock. Declare `files` completely and accurately — under-declaring causes',
    'two agents to edit one file at once, which is the failure mode this whole structure exists to prevent.',
    'Over-declaring costs you time; under-declaring costs you the work.',
    '',
    'Slices that share a file run one after another. If overlap would force MORE THAN FOUR slices into one serial',
    'chain, MERGE adjacent members of that chain into fewer, larger slices (a merged slice still gets one fresh',
    'agent). Every serialised slice pays a fixed cost — a cold agent reading the repo and its spec — so',
    'twelve one-hour-apart micro-slices are slower and dearer than five, and no safer.',
    '',
    'Each slice prompt must be SELF-CONTAINED: its implementer sees only task_summary, shared_context and that',
    'prompt — NOT the full task text. When the task points at a plan or spec document with per-task sections,',
    'give the slice its section as a POINTER (file path + heading + line range) and tell the implementer to read',
    'only that section plus the document\'s global-constraints section, never the whole file. Do not paste the',
    'section into the prompt.',
    'Put anything common (conventions, the check command, where things live, what NOT to touch) in shared_context,',
    'carrying forward the recon notes above so each implementer does not re-read the repo to learn them.',
    'shared_context is also the main cost lever you control. Every implementer starts cold and re-reads the repo',
    'for itself; a fact you establish once here is read once instead of N times. Be generous with it — file',
    'layout, the exact check command, naming conventions, the gotcha that would otherwise cost each agent three',
    'tool calls to rediscover. Terse slices plus a thin shared_context is the expensive shape.',
    '',
    'Slice in whatever unit this repo is actually made of. That is source files for an application, but it may be',
    'modules or environment directories for Terraform, charts for Helm, or migrations for a schema change. What',
    'matters is only that two slices never touch the same file.',
    (HAS_CHECKS
      ? ''
      : '\nThis repo has NOTHING executable to run, so no slice can be proven by running it. Prefer slices whose\n' +
      'correctness is legible in the diff, and note in shared_context that review is the only gate.'),
    '',
    'If some part of the task cannot be sliced or you deliberately left it out, list it in `uncovered`. Do not',
    'silently drop scope — an honest gap is useful, a hidden one is not. `uncovered` is read mechanically: any',
    'entry there makes the run not ok, so it holds ONLY dropped scope — never a caveat, a dependency note or a',
    'sentence saying nothing was dropped. Everything of that kind goes in `notes`.',
    '',
    'Write no code. Make no commits.',
  ].join('\n'),
    { label: 'slice', phase: 'Slice', model: JUDGE, effort: EFFORT, schema: PLAN_SCHEMA }
  )
}

if (!plan || !plan.slices || !plan.slices.length) {
  return { ok: false, stage: 'plan', error: 'planner returned no slices', plan, recon: recon }
}

// With the orchestrator's slices no slicer carried Recon's notes into the shared context,
// so the engine appends them itself: the check command, the layout and the conventions are
// what every cold implementer would otherwise spend three tool calls rediscovering.
const RECON_NOTES = SLICES_IN
  ? [
    'WHAT RECON ESTABLISHED — trust this and do not re-derive it:',
    'repo: ' + (recon.ecosystem || 'unknown') + ' on branch ' + (recon.branch || '?') + ' @ ' + BASE.slice(0, 8),
    (HAS_CHECKS ? 'check command: ' + CHECK_CMD : 'no executable checks: nothing here can be run, so keep every commit small and legible in the diff'),
    (recon.layout_notes ? 'layout: ' + recon.layout_notes : ''),
    (recon.conventions ? 'conventions (binding): ' + recon.conventions : ''),
  ].filter(Boolean).join('\n')
  : ''
// The orchestrator's context comes first and is honoured on the slicer path too: the
// slicer's shared_context is a cold agent's reading of the repo, the orchestrator's is a
// constraint ("never touch vendor/"), and a constraint silently dropped because the
// slices were left to the engine is the failure the ignore-out-loud rule exists to stop.
const SHARED = SLICES_IN
  ? [SHARED_CONTEXT_IN, RECON_NOTES].filter(Boolean).join('\n\n')
  : [FROM === 'slices' ? SHARED_CONTEXT_IN : '', String(plan.shared_context || '')].filter(Boolean).join('\n\n')
// What implementers and patchers see instead of the full task: every agent that carried
// the whole brief re-read it on every turn (plan C: 53 agents, a 4,200-line plan each).
// The adversary keeps the full TASK — it is the bar, and the adversary is the judge.
const TASK_BRIEF = (FROM === 'slices' ? TASK_SUMMARY_IN : '') || String(plan.task_summary || '').trim() || TASK
// Two-dot: literally "everything added between BASE and HEAD". Three-dot would
// route through merge-base, which is identical while history stays linear and
// quietly different the moment it does not.
const DIFF_CMD = 'git diff ' + BASE + '..HEAD'

if (plan.notes && plan.notes.length) log('planner notes: ' + plan.notes.join(' | '))
if (plan.uncovered && plan.uncovered.length) {
  log('planner left uncovered: ' + plan.uncovered.join(' | '))
}

const groups = groupByFileConflict(plan.slices)
const biggestGroup = groups.reduce((n, g) => Math.max(n, g.slices.length), 0)
// The plan block the cost-gate pause, an out-of-budget stop and the final report carry.
function planReport() {
  return { slices: plan.slices, groups: groups.length, largest_group: biggestGroup, uncovered: plan.uncovered || [], notes: plan.notes || [],
    source: SLICES_IN ? 'orchestrator' : 'slicer' }
}
log(plan.slices.length + ' slice(s) -> ' + groups.length + ' conflict-free group(s) (largest holds ' +
  biggestGroup + '), up to ' + WAVE + ' group(s) at a time')
if (groups.length === 1 && plan.slices.length > 2) {
  log('WARNING: all ' + plan.slices.length + ' slices merged into ONE group — their declared files overlap ' +
    'transitively, so nothing can run concurrently. Each slice still gets its own agent; this run ' +
    'will be slow, not large.')
}

// ---------------------------------------------------------------------------
// The cost gate — what the rest of the run would cost at API list prices.
// ---------------------------------------------------------------------------
const spentCounts = {
  probe: PROBE_MODELS ? PRIMARY_MODELS.length : 0,
  recon: 1,
  spec: documents.spec ? 1 : 0,
  doc_review: documents.spec_reviews.filter((r) => r.review).length + documents.plan_reviews.filter((r) => r.review).length +
    [...documents.spec_reviews, ...documents.plan_reviews].filter((r) => r.edit).length,   // an editor lane is priced like a review
  plan_doc: documents.plan && FROM !== 'plan' ? 1 : 0,
  plan_review: documents.plan_reviews.filter((r) => r.review).length,
  answers: (answersFor('spec').length ? 1 : 0) + (answersFor('plan').length ? 1 : 0),
  plan_index: planReindexed ? 1 : 0,
  slice: SLICES_IN ? 0 : 1,
}
const nSlices = plan.slices.length
// Measured: the first review raised about one finding per slice; ~60% sat at or above
// "major". The per-round cap and the severity gate bound it from above.
const patchedPerRound = Math.min(MAX_PATCH_PER_ROUND, Math.max(2, Math.round(nSlices * (PATCH_SEVERITY === 'minor' ? 1.0 : PATCH_SEVERITY === 'critical' ? 0.25 : 0.6))))
const aheadCounts = {
  implement: nSlices,
  review: 1 + MAX_ROUNDS,
  patch: MAX_ROUNDS * patchedPerRound,
}
const est = estimateRun(PROFILE, PRICES, spentCounts, aheadCounts)
const estimate = {
  currency: 'USD',
  basis: 'Anthropic first-party API list prices (a non-subscription licence), cached 2026-06-24; per-agent token profile measured over six runs on 2026-09-09..11. Subscription users are not billed per token: this is the size of the run at list prices.',
  prices_per_mtok: PRICES,
  slices: nSlices,
  patch_rounds: MAX_ROUNDS,
  expected_patched_findings_per_round: patchedPerRound,
  spent_so_far_usd: est.spent_usd,
  ahead_usd: est.ahead_usd,
  ahead_low_usd: +(est.ahead_usd * 0.6).toFixed(2),
  ahead_high_usd: +(est.ahead_usd * 1.6).toFixed(2),
  total_expected_usd: +(est.spent_usd + est.ahead_usd).toFixed(2),
  of_which_from_unmeasured_assumptions_usd: est.assumed_usd,
  output_tokens_actually_spent_this_turn: budget.spent(),
  breakdown: est.lines,
  note: 'The low/high band is a fixed 0.6x-1.6x of the expected figure, the rough spread the six measured runs showed; it is not a per-slice-count measurement. A fallback lane (Fable at ~2x Opus) is not in the figure; models.fallbacks.used in the final result says if one ran.',
}
log('COST ESTIMATE at API list prices: ~$' + est.spent_usd + ' spent so far, ~$' + est.ahead_usd +
  ' ahead ($' + estimate.ahead_low_usd + '–$' + estimate.ahead_high_usd + ') for ' + nSlices + ' slice(s), ' +
  MAX_ROUNDS + ' patch round(s); total ~$' + estimate.total_expected_usd)
// maxUsd only ever passes a FINITE total: a broken price table must pause, not wave through.
const withinCeiling = MAX_USD !== null && Number.isFinite(estimate.total_expected_usd) && estimate.total_expected_usd <= MAX_USD
if (!APPROVE_ESTIMATE && !withinCeiling) {
  log('PAUSED at the cost gate — relaunch with approveEstimate:true (or maxUsd) to build')
  return {
    ok: true,
    paused: true,
    stage: 'estimate',
    estimate: estimate,
    how_to_resume: 'Show the user the estimate (expected, the low–high band, what is measured vs assumed) and ask whether to ' +
      'proceed. On yes, relaunch this workflow with the SAME script and resumeFromRunId, and args identical plus ' +
      'approveEstimate:true (or maxUsd:<their ceiling>). Every agent before this gate replays from cache. On no, stop: the ' +
      'documents are committed on the branch and nothing has been implemented.',
    plan: planReport(),
    documents: documentsReport(),
    recon: recon,
  }
}

// ===========================================================================
// src/92-implement.js
// ===========================================================================
// ---------------------------------------------------------------------------
// Phase 2 — Implement. ONE AGENT PER SLICE, always. A group means "these run in
// order", not "these share a context": file-disjointness governs concurrency and
// nothing else. Merging N slices into one agent is how a run ends up with a
// single 600k-token context and no verification until the very end.
// ---------------------------------------------------------------------------
phase('Implement')

// The early return every phase below uses when the token budget is nearly gone.
function outOfBudget(stage, extra) {
  log('stopping before ' + stage + ': ' + Math.round(budget.remaining() / 1000) + 'k tokens left in the turn\'s budget')
  return { ok: false, stage: stage, error: 'token budget nearly exhausted before ' + stage + ' (' + Math.round(budget.remaining() / 1000) + 'k left); nothing past this point ran',
    base_sha: BASE, diff_command: DIFF_CMD, recon: recon, documents: documentsReport(),
    plan: planReport(),
    lane_errors: laneErrors, ...(extra || {}) }
}
if (!budgetLeft(60000)) return outOfBudget('implement')

function implPrompt(s, landedSiblings) {
  return [
    'You are the IMPLEMENTER. Write the code for the ONE slice below and commit it.',
    '',
    'THE TASK IN BRIEF (context — do NOT implement any of it beyond your slice; obey every constraint in it):',
    TASK_BRIEF,
    '',
    'SHARED CONTEXT:',
    SHARED,
    '',
    'YOUR SLICE — this is the whole of your job:',
    sliceBlock(s),
    '',
    (landedSiblings.length
      ? 'Slices touching your files have ALREADY landed ahead of you in this run: ' +
      landedSiblings.map((d) => d.slice.id + ' (' + d.slice.title + ')').join(', ') +
      '.\nTheir work is in the tree. Build on it; do not revisit, revert or re-do it.\n'
      : ''),
    DOCTRINE_TDD,
    'RULES:',
    '- Implement this slice and nothing else. Return exactly one entry in slice_results.',
    '- Touch only the files your slice declares. If you genuinely must touch another, do it and SAY SO in notes.',
    '- Follow the repo\'s own conventions. Read its CLAUDE.md / AGENTS.md first if it has one.',
    '- ' + TEST_LINE,
    (HAS_CHECKS
      ? '- Where the repo has a real test suite, write the test first, watch it fail, then make it pass. Where its\n' +
      '  only checks are lint/validate/build, run those instead — the point is that something executes and can fail.\n' +
      '- Run that command before you commit, and report it in checks_run / checks_passed.'
      : '- There is nothing executable to run here, so do NOT claim you ran anything: leave checks_run empty and\n' +
      '  checks_passed false. Compensate by keeping the commit small and self-evident in the diff, since a\n' +
      '  reviewer reading it is the only gate this work will get.'),
    '- Commit with a clear message, and commit BY PATHSPEC: `git add <file>` for each file you edited, then',
    '  `git commit -m "<message>" -- <file> <file>…` naming the same files. The index is shared with other',
    '  implementers working in this tree at the same time; a plain `git commit` would carry whatever they have',
    '  staged into your commit, and `git commit -- <files>` commits only the paths you name. Never `git add -A`,',
    '  `git add .` or `git commit -a`: a sweep commits their half-written work under your name. If git fails on',
    '  `index.lock`, wait a moment and retry; do not delete the lock.',
    '- Do NOT push. Do NOT merge or rebase branches. Do NOT amend commits you did not make. Do NOT stash, reset or',
    '  check out anything: the tree is shared.',
    '- If the check fails on a file outside your slice that you did not touch, another implementer may be mid-edit:',
    '  re-run once after a short wait, and if it still fails say exactly that in notes rather than "fixing" their file.',
    '- If the slice defeats you, commit what is genuinely correct and report it as partial or failed.',
    '',
    'Another model that did not write this code will review the real diff and re-run whatever this repo can',
    'run. Claiming a check passed when you did not run it will be caught, so report exactly what you ran and',
    'exactly what happened.',
  ].join('\n')
}

// A group's slices are serialised because they share files. Each still gets a
// fresh agent, so context stays bounded by the slice, not by the group.
async function implementGroup(group) {
  const landed = []
  for (const s of group.slices) {
    const impl = await callAgent(implPrompt(s, landed), {
      label: 'impl:' + s.id,
      phase: 'Implement',
      model: CODER,
      effort: EFFORT,
      schema: IMPL_SCHEMA,
    })
    landed.push({ slice: s, impl: impl })
  }
  return landed
}

const built = (await runGroups(groups, WAVE, implementGroup, 'implement wave')).filter(Boolean).flat()
// callAgent never throws, so a group can only go missing if the runtime dropped it;
// name the slices rather than let the count quietly shrink.
const neverRan = plan.slices.filter((s) => !built.some((b) => b.slice.id === s.id)).map((s) => s.id)
const notImplemented = built.filter((b) => !b.impl).map((b) => b.slice.id)
if (neverRan.length) log('WARNING: ' + neverRan.length + ' slice(s) never ran (the runtime dropped their group): ' + neverRan.join(', '))
if (notImplemented.length) log('WARNING: ' + notImplemented.length + ' slice(s) had no implementer result after the fallback: ' + notImplemented.join(', '))
const violations = footprintViolations(built, groups)
if (violations.length) log('WARNING: ' + violations.length + ' undeclared file(s) touched inside another group\'s footprint: ' +
  violations.map((v) => v.slice + ' -> ' + v.file + ' (declared by ' + v.collides_with.join(', ') + ')').join('; '))

log('implemented ' + built.length + '/' + plan.slices.length + ' slice(s)')
// The implementers' own reports, as the adversary sees them: claims, not evidence.
const implReports = built.map((b) => ({ slice: b.slice.id, impl: b.impl }))

function sliceBlock(s) {
  return [
    '--- SLICE ' + s.id + ': ' + s.title,
    'what:      ' + s.prompt,
    'files:     ' + (s.files || []).join(', '),
    'done when: ' + s.done_when,
  ].join('\n')
}

// ===========================================================================
// src/94-review.js
// ===========================================================================
// ---------------------------------------------------------------------------
// Phase 3 — Adversarial review. BARRIER: the adversary needs the whole diff, and it is
// the one lane that executes the check after the implementers' self-reported runs.
// There is no per-slice verifier: every slice's verifier used to run the same check on
// the same tree (a shared checkout cannot be rewound per commit) and hand a verdict to
// the adversary, which was told to re-check it against the diff anyway. Measured over
// six runs the phase was 12% of wall clock and 8% of tokens for verdicts the next gate
// re-derived. The verifier's hunt list and its check run moved into the adversary.
// ---------------------------------------------------------------------------
function reviewPrompt(roundLabel, extra) {
  return [
    'You are the ADVERSARIAL REVIEWER. Your job is to REFUTE the claim that this work is complete and correct.',
    'You are not here to be reassuring, and a clean verdict you cannot defend is worse than a false alarm.',
    '',
    'OVERALL TASK — this is the bar the work must clear:',
    TASK_TEXT,
    '',
    (PLAN_PATH ? 'THE PLAN DOCUMENT THE WORK MUST MATCH, task by task: ' + PLAN_PATH + (SPEC_PATH ? ' (spec: ' + SPEC_PATH + ')' : '') : ''),
    'THE SLICES THAT WERE EXECUTED:',
    JSON.stringify(plan.slices.map((s) => ({ id: s.id, title: s.title, done_when: s.done_when })), null, 2),
    (plan.uncovered && plan.uncovered.length ? '\nThe planner already admitted leaving out: ' + plan.uncovered.join(' | ') : ''),
    (violations.length ? '\nIMPLEMENTERS THAT TOUCHED A FILE ANOTHER SLICE DECLARED (two agents may have edited it at once — read those files with suspicion):\n' +
      violations.map((v) => '  ' + v.slice + ' touched ' + v.file + ', declared by ' + v.collides_with.join(', ')).join('\n') : ''),
    '',
    'WHAT THE IMPLEMENTERS CLAIM — their own reports. Claims, not evidence: checks_passed is self-reported and',
    'nobody has re-run anything since. Read the notes for files touched outside a slice and for anything left undone:',
    JSON.stringify(implReports, null, 2),
    '',
    (extra || ''),
    'READ THE ACTUAL DIFF YOURSELF — do not review the reports:',
    '  ' + DIFF_CMD,
    'Set diff_reviewed:true only if you ran that and read the output.',
    'Then run `git status --porcelain` and report it verbatim in dirty_paths: anything uncommitted is work the',
    'diff does not contain, and a check that passed on it proves nothing about the branch.',
    (HAS_CHECKS
      ? 'RUN THE CHECK YOURSELF. ' + TEST_LINE + ' You are the only lane in this run that executes it after the code\n' +
        'was written: paste the real tail into output_tail, the command into commands_run, and set executed:true. A\n' +
        'failing check is a finding (critical) with the output as its failure_scenario. A review that did not run\n' +
        'the check is executed:false and can never be clean. If you could not run it (broken env, missing\n' +
        'credentials), say so plainly and return executed:false.'
      : 'There is nothing executable in this repo. ' + TEST_LINE + ' Set executed:false and checks_available:false.'),
    '',
    'THE REPO YOU ARE REVIEWING: ' + (recon.ecosystem || 'unknown') +
    (HAS_CHECKS ? '. Its check command is: ' + CHECK_CMD : '. It has NO executable checks.'),
    (recon.conventions ? 'Conventions it documents, which a violation of IS a finding:\n' + recon.conventions : ''),
    '',
    'HUNT SPECIFICALLY FOR:',
    '- Requirements in the task that NO slice implemented. The gap the plan itself missed is the finding no',
    '  single implementer could see, and it is the main reason you exist.',
    '- Integration seams: an assumption slice A relies on that slice B quietly changed.',
    '- Behaviour the diff changes that no test or check covers.',
    '- Edge and error paths: empty, null, zero, negative, very large, unicode, concurrent, partial failure.',
    '- Anything an implementer reported done, or a check it reported passed, that the diff does not support.',
    '- Files touched outside a slice\'s declared set; tests or checks weakened, skipped or deleted to make things',
    '  pass; TODO stubs standing in for the work; commented-out assertions; except/catch blocks that swallow the',
    '  error a check was supposed to surface; a value hardcoded where it should be derived.',
    '- Defects in whatever idiom this repo is written in, not just general-purpose code smells. For infrastructure',
    '  that means things like a resource replaced where it should be updated in place, state or lifecycle rules',
    '  dropped, a hardcoded account/region/environment, a secret committed, a permission widened beyond the task,',
    '  or a change that silently destroys data on apply. Judge the diff on its own terms.',
    '',
    DOCTRINE_REVIEW_CALIBRATION,
    'RULES:',
    '- Under uncertainty, default to raising the finding. A false positive costs one patch; a false negative ships.',
    (HAS_CHECKS
      ? ''
      : '- Nothing here can be executed, so the diff is the only evidence. Weigh it accordingly and say so in summary.'),
    '- Every finding needs a concrete failure_scenario: specific inputs or state leading to a specific wrong',
    '  result. "This is fragile", "consider extracting", "could be clearer" are NOT findings — drop them.',
    '- Style, naming and formatting are not findings unless the repo\'s own documented convention is violated.',
    '- clean:true ONLY if you read the whole diff' + (HAS_CHECKS ? ', ran the check and saw it pass,' : '') + ' and found nothing meeting that bar. Say so in summary.',
    '- You review. You do not fix, and you do not commit.',
    (roundLabel ? '\nThis is ' + roundLabel + '.' : ''),
  ].join('\n')
}

// Finding ids are namespaced by the review that raised them ("r0:F1", "r1:F1"): every
// reviewer numbers from F1, and a round-1 handed-off F3 used to be conflated with a
// brand-new F3 from the re-review. `re_raises` (set by a re-review) refers to these ids.
function stampReview(rev, n) {
  if (!rev) return rev
  const judged = judgeReview(rev, HAS_CHECKS)
  return { ...judged, findings: namespaced('r' + n, judged.findings) }
}

phase('Review')
if (!budgetLeft(40000)) return outOfBudget('review', { never_ran: neverRan, not_implemented: notImplemented, implementation: implReports })
let review = stampReview(await callAgent(reviewPrompt('the first review', ''), {
  label: 'adversary:r0',
  phase: 'Review',
  model: JUDGE,
  effort: EFFORT,
  schema: REVIEW_SCHEMA,
}), 0)
const firstReview = review
// True when the LAST review lane (first or a re-review) returned nothing after its
// fallback. Then nothing is known to be closed and the result says so, loudly.
let reviewMissing = !review
if (reviewMissing) log('WARNING: the adversarial review returned nothing after the fallback — this work is UNREVIEWED')

// ---------------------------------------------------------------------------
// Phase 4 — Patch rounds. Stops the moment a review comes back clean.
// ---------------------------------------------------------------------------
const rounds = []
let round = 0

while (
  round < MAX_ROUNDS &&
  review &&
  review.clean !== true &&
  Array.isArray(review.findings) &&
  review.findings.length > 0
) {
  if (!budgetLeft(60000)) {
    log('stopping before patch round ' + (round + 1) + ': ' + Math.round(budget.remaining() / 1000) + 'k tokens left in budget')
    break
  }
  round++
  phase('Patch')

  const ranked = [...review.findings].sort((a, b) => severityRank(a.severity) - severityRank(b.severity))
  const eligible = ranked.filter((f) => severityRank(f.severity) <= severityRank(PATCH_SEVERITY))
  const handedOff = ranked.filter((f) => severityRank(f.severity) > severityRank(PATCH_SEVERITY))
  if (eligible.length === 0) {
    round--
    log('no finding at or above "' + PATCH_SEVERITY + '" — nothing to auto-patch; ' + handedOff.length +
      ' finding(s) handed to the orchestrator: ' + handedOff.map((f) => f.id).join(', '))
    break
  }
  const take = eligible.slice(0, MAX_PATCH_PER_ROUND)
  const deferred = eligible.slice(MAX_PATCH_PER_ROUND)
  log('round ' + round + ': patching ' + take.length + ' finding(s)' +
    (deferred.length ? ', DEFERRING ' + deferred.length + ' — ' + deferred.map((f) => f.id).join(', ') : '') +
    (handedOff.length ? '; ' + handedOff.length + ' below "' + PATCH_SEVERITY + '" handed to the orchestrator' : ''))

  // Patchers used to run all at once in the shared tree, one per finding, and kept
  // meeting sibling patchers' uncommitted edits. Same cure as the implement phase:
  // findings that name the same file run one after another, groups run in parallel.
  // No per-patch verifier: the re-review reads every patch diff, judges whether the
  // finding is genuinely closed and runs the check — the same verdict the verifier
  // gave, re-derived, so the verifier was a second serial lane per patch for nothing.
  const patchGroups = groupByFileConflict(take.map((f) => ({ id: f.id, files: patchFootprint(f), finding: f })))
  log('round ' + round + ': ' + take.length + ' patch(es) in ' + patchGroups.length + ' file-disjoint group(s)')

  function patchOne(f) {
    return callAgent(
        [
          'You are the PATCHER. Fix exactly one review finding.',
          '',
          'THE TASK IN BRIEF (context only; obey every constraint in it):',
          TASK_BRIEF,
          '',
          'THE FINDING:',
          JSON.stringify(f, null, 2),
          '',
          DOCTRINE_DEBUG,
          'RULES:',
          '- Fix this finding. Do not refactor, tidy or improve anything beyond it — a patch round is the worst',
          '  possible moment to widen scope.',
          (HAS_CHECKS
            ? '- Add a regression test that FAILS before your fix and PASSES after. Verify both directions if you can.\n' +
            '  If this repo has no test framework, add whatever check it DOES support that would have caught this\n' +
            '  (a lint rule, a validate step, an assertion in an existing script). If nothing is possible, say why\n' +
            '  in regression_test rather than leaving it blank.\n' +
            '- ' + TEST_LINE + ' Run the whole thing, not just your new case.'
            : '- ' + TEST_LINE + ' So there is no regression test to add: explain in regression_test what would have\n' +
            '  caught this if the repo could run anything, and leave checks_passed false rather than implying a pass.'),
          '- Commit BY PATHSPEC: `git add <file>` for each file you edited, then `git commit -m "<message>" -- <file> <file>…`',
          '  naming the same files, with the finding id in the message. The index is shared with other patchers in this',
          '  tree; `git commit -- <files>` commits only the paths you name. Never `git add -A`, `git add .` or',
          '  `git commit -a`. Do NOT push.',
          '- If you believe the finding is WRONG, do not quietly skip it and do not "fix" it anyway: return',
          '  status "disputed" with the concrete evidence that refutes it. An unevidenced dispute will be',
          '  treated as a failure.',
        ].join('\n'),
      { label: 'patch:' + f.id, phase: 'Patch', model: CODER, effort: EFFORT, schema: PATCH_SCHEMA }
    ).then((p) => ({ finding: f, patch: p }))
  }

  // A patcher that returned nothing or reported `failed` is logged here; the finding is
  // carried to the orchestrator by collectForOrchestrator either way.
  async function patchGroup(group) {
    const out = []
    for (const item of group.slices) {
      const p = await patchOne(item.finding)
      if (!p) continue
      if (!p.patch || p.patch.status === 'failed') {
        log('patch ' + item.finding.id + ': ' + (p.patch ? 'patcher reported failed' : 'patcher returned nothing'))
      }
      out.push(p)
    }
    return out
  }

  const patched = (await runGroups(patchGroups, WAVE, patchGroup, 'patch wave')).filter(Boolean).flat()

  const done = patched.filter(Boolean)
  rounds.push({ round: round, patched: done, deferred: deferred, handed_off: handedOff })
  log('round ' + round + ': ' + done.filter((p) => p.patch && p.patch.status === 'fixed').length + ' fixed, ' +
    done.filter((p) => p.patch && p.patch.status === 'disputed').length + ' disputed, ' +
    done.filter((p) => !p.patch || p.patch.status === 'failed').length + ' failed')

  phase('Review')
  if (!budgetLeft(40000)) {
    log('stopping before re-review ' + round + ': ' + Math.round(budget.remaining() / 1000) + 'k tokens left in budget — the patches are UNREVIEWED')
    review = null
    reviewMissing = true
    break
  }
  review = stampReview(await callAgent(
    reviewPrompt(
      'review round ' + round + ' of at most ' + MAX_ROUNDS,
      [
        'PATCHES APPLIED SINCE THE LAST REVIEW — the patchers\' own reports; checks_passed is self-reported and',
        'nobody has verified a patch before you. `git show <commit_sha>` each one:',
        JSON.stringify(done.map((p) => ({ finding_id: p.finding.id, claim: p.finding.claim, failure_scenario: p.finding.failure_scenario, patch: p.patch })), null, 2),
        (deferred.length ? 'DEFERRED, NOT PATCHED (already on the orchestrator\'s list; do not re-raise unless a patch made one worse): ' +
          deferred.map((f) => f.id + ' (' + f.claim + ')').join(' | ') : ''),
        (handedOff.length ? 'HANDED TO THE ORCHESTRATOR, NOT PATCHED (below the auto-patch severity; already on their list; do not re-raise unless a patch made one worse): ' +
          handedOff.map((f) => f.id + ' (' + f.claim + ')').join(' | ') : ''),
        '',
        'Two jobs this round, and the second is the one people forget:',
        '(a) Is each patched finding above GENUINELY closed? Read the patch diff: does it close the failure_scenario or',
        '    merely make the symptom go away; does the regression test exercise the scenario, or would it pass on the',
        '    old code? If not closed, raise it again as a finding with `re_raises` set to the earlier id (e.g. "r0:F2")',
        '    so it is not counted twice.',
        '(b) Did the patches themselves introduce anything new? Patch rounds are written under time pressure and',
        '    are a common source of fresh defects. Review their diffs as adversarially as the original work.',
        'A finding the patcher disputed with sound evidence should NOT be re-raised — say so in summary instead; the',
        'dispute is handed to the orchestrator with its evidence regardless.',
        '',
      ].join('\n')
    ),
    { label: 'adversary:r' + round, phase: 'Review', model: JUDGE, effort: EFFORT, schema: REVIEW_SCHEMA }
  ), round)
  reviewMissing = !review
  if (reviewMissing) log('WARNING: re-review ' + round + ' returned nothing after the fallback — the patches are UNREVIEWED')
}

// ===========================================================================
// src/96-report.js
// ===========================================================================
// ---------------------------------------------------------------------------
// Report
// ---------------------------------------------------------------------------
const openFindings = review ? review.findings : []
const stoppedEarly = round >= MAX_ROUNDS && openFindings.length > 0
// The first review runs at the barrier after every implementer has finished, so the
// tree should be clean there; anything it found uncommitted is work outside the diff.
const uncommittedAtReview = firstReview ? firstReview.dirty_paths : ''

// Everything the orchestrator must close by hand, at EVERY severity — see
// collectForOrchestrator for what counts. With no final review, every patched
// finding is carried too, because nothing confirmed it closed.
const forOrchestrator = collectForOrchestrator(openFindings, rounds, !reviewMissing)
const bySeverity = { critical: 0, major: 0, minor: 0 }
for (const f of forOrchestrator) bySeverity[f.severity] = (bySeverity[f.severity] || 0) + 1
if (forOrchestrator.length) {
  log('FOR THE ORCHESTRATOR TO CLOSE BY HAND: ' + forOrchestrator.length + ' finding(s) — ' +
    bySeverity.critical + ' critical, ' + bySeverity.major + ' major, ' + bySeverity.minor + ' minor: ' +
    forOrchestrator.map((f) => f.id + ' (' + f.severity + ')').join(', '))
}

if (stoppedEarly) {
  log('STOPPED at the ' + MAX_ROUNDS + '-round cap with ' + openFindings.length + ' finding(s) still open')
} else if (openFindings.length === 0) {
  log('adversarial review came back clean after ' + round + ' patch round(s)')
}

if (fallbacksUsed.length) {
  log(fallbacksUsed.length + ' lane(s) ran on a FALLBACK model after the primary returned nothing: ' +
    fallbacksUsed.map((f) => f.label + ' -> ' + f.fallback).join(', '))
}
if (laneErrors.length) {
  log(laneErrors.length + ' lane failure(s) recorded: ' + laneErrors.map((e) => e.label + ' (' + e.error.slice(0, 60) + ')').join(', '))
}

// ok is mechanical: true only when the run completed AND every gate passed. Every
// reason it did not is listed in not_ok, so a consumer keying off ok alone cannot
// mistake a half-built, unexecuted, unreviewed or dirty run for a success. The rest
// of the report is still here either way — the work exists on the branch.
const notOk = []
if (reviewMissing) notOk.push('the adversarial review returned nothing after its fallback: the work is unreviewed')
if (neverRan.length) notOk.push(neverRan.length + ' slice(s) never ran: ' + neverRan.join(', '))
if (notImplemented.length) notOk.push(notImplemented.length + ' slice(s) not implemented (no implementer result): ' + notImplemented.join(', '))
if (plan.uncovered && plan.uncovered.length) notOk.push('the slicer left scope uncovered: ' + plan.uncovered.join(' | '))
if (violations.length) notOk.push(violations.length + ' undeclared file(s) touched inside another group\'s footprint: ' + violations.map((v) => v.slice + ' -> ' + v.file).join(', '))
if (uncommittedAtReview) notOk.push('uncommitted changes in the tree at review time (not in the reviewed diff): ' + uncommittedAtReview.slice(0, 300))
if (review && review.diff_reviewed !== true) notOk.push('the final review did not read the diff (diff_reviewed:false)')
if (review && HAS_CHECKS && review.executed !== true) notOk.push('the final review did not run the check command (executed:false): nothing independent executed the suite')
if (review && openFindings.length) notOk.push('the final review is not clean: ' + openFindings.length + ' finding(s) open')
if (notOk.length) log('NOT OK — ' + notOk.join('; '))

return {
  ok: notOk.length === 0,
  not_ok: notOk,
  ...(reviewMissing ? { stage: 'review', error: 'the adversarial review returned nothing after its fallback; the work on the branch is UNREVIEWED and every finding of the last round is carried in for_orchestrator', review_missing: true } : { review_missing: false }),
  ...(neverRan.length ? { stage: 'implement', error: neverRan.length + ' slice(s) never ran: ' + neverRan.join(', ') } : {}),
  task: TASK,
  base_sha: BASE,
  diff_command: DIFF_CMD,
  repo: {
    ecosystem: recon.ecosystem || '',
    branch: recon.branch || '',
    check_command: CHECK_CMD || null,
    // The honest caveat: false means no lane in this run executed anything, so
    // the review's verdict rests on reading alone. Report it, do not bury it.
    executable_checks: HAS_CHECKS,
    other_checks: (recon.verify_commands || []).slice(1),
  },
  paused: false,
  // The pre-build estimate, and the one actual figure the runtime exposes: output tokens
  // spent this turn across the main loop and every workflow. Compare the two.
  cost: { estimate: estimate, output_tokens_actually_spent_this_turn: budget.spent() },
  patch_policy: { max_rounds: MAX_ROUNDS, auto_patch_at_or_above: PATCH_SEVERITY },
  // The front half: where the run started, the documents it wrote and committed, every
  // adversarial review and fold-in of them, and — first thing to report — every decision a
  // writer took because there was no owner to ask.
  documents: { ...documentsReport(), doc_rounds: DOC_ROUNDS, pause_for_owner: PAUSE_FOR_OWNER },
  models: {
    // What actually ran, not what the engine pins by default: docWriter / docJudge move
    // the first four of these, and a result that named the default would misreport which
    // model reviewed the spec.
    spec: DOC_WRITER, plan: DOC_WRITER, doc_review: DOC_JUDGE, owner_answers: DOC_JUDGE,
    implement: CODER, review: JUDGE, slice: SLICES_IN ? 'orchestrator' : JUDGE, recon: CODER, probed: PRIMARY_MODELS,
    effort: EFFORT, max_concurrent: WAVE,
    // Lanes whose primary model returned nothing and were re-run once on the other
    // tier. A verdict from a fallback lane is still a verdict, but say which model gave it.
    fallbacks: { enabled: FALLBACK, coder: CODER_FALLBACK, judge: JUDGE_FALLBACK, used: fallbacksUsed },
  },
  plan: planReport(),
  // The implementers' own reports, unjudged: the adversary's findings are the verdict on them.
  implementation: implReports,
  // Slices the runtime dropped before an implementer ran, and slices whose implementer
  // (and its fallback) returned nothing: neither has a commit to review.
  never_ran: neverRan,
  not_implemented: notImplemented,
  uncommitted_at_review: uncommittedAtReview,
  // Files an implementer touched outside its slice that another group had declared:
  // two agents may have been inside that file at once.
  footprint_violations: violations,
  // Every lane that returned nothing or threw, primary or fallback, with the reason.
  lane_errors: laneErrors,
  // Where the minutes went: wall clock for the run, agent-seconds per phase, and every lane.
  timing: timingByPhase(laneTimings, elapsed(RUN_T0)),
  patch_rounds: rounds,
  final_review: review,
  open_findings: openFindings,
  // The complete to-do for the orchestrator, every severity included (minors too):
  // the last review's findings plus everything handed off or deferred in any round.
  // The skill makes closing ALL of these, by hand, the orchestrator's last step.
  for_orchestrator: forOrchestrator,
  for_orchestrator_by_severity: bySeverity,
  stopped_at_round_cap: stoppedEarly,
}
